/* Questions of the Telegram mini app: 50 per training, taken from the
   website's banks. Generated by tools/tg-miniapp/build.py: do not edit. */
window.TG_DATA={"v":1,"n":50,"sets":[{"id":"g_base","sec":"Grammar","title":"Structure & tenses","desc":"Sentence structure, tenses, modals","items":[{"q":"It was not until 1998 ______ the treaty was ratified.","o":["when","that","which","then"],"a":1,"e":"It was not until ... that (emphatic structure)."},{"q":"When you finally get back home, please _____ me a postcard.","o":["to send","send","sent","be sent"],"a":1,"e":"*Imperative*. A request. \"You\" is omitted from the main clause."},{"q":"If you had been here yesterday, you _____ my wife.","o":["could meet","met","will meet","could have met"],"a":3,"e":"\"*If*\" clause. *Past unreal* because of \"yesterday.\""},{"q":"All of the furniture _____ by the floodwaters.","o":["is damage","were damage","was damaged","will have been damage"],"a":2,"e":"\"Furniture\" is a mass noun. Mass nouns take singular verbs."},{"q":"We were putting up our tents when it _____.","o":["began snow","began to snow","begun the snow","begins snowing"],"a":1,"e":"gerund. *It began to snow* or *it began snowing*."},{"q":"If I had not eaten so much pizza last night, I _____ so sick right now.","o":["would not be","will not be","am not","would not have been being"],"a":0,"e":"This is a mixed structure \"*If*\" clause. The time words \"last night\" and \"right now\" something *had not happened* last night."},{"q":"They honeymooned _____ Brussels.","o":["in","at","of","for"],"a":0,"e":"Cities take *in*. So do countries, counties, towns"},{"q":"My car is parked _____ the red Toyota and the white Cadillac.","o":["under","between","on","around"],"a":1,"e":"We use \"between\" when we are taking about *two* specific things."},{"q":"A submarine is designed to function _____ the water for long periods of time.","o":["under","above","during","between"],"a":0,"e":"\"Sub\" is a prefix meaning \"under,\" so it follows that a submarine can function *under* the surface of the water."},{"q":"May I borrow $300 _____ you?","o":["of","to","by","from"],"a":3,"e":"You *borrow from* someone. You can *loan to*. You can *lend* to."},{"q":"Their new business will be located _____ Fulton Street.","o":["at","in","on","for"],"a":2,"e":"Name of the street by itself. No address number given."},{"q":"I want another glass _____ milk.","o":["for","to","with","of"],"a":3,"e":"Something and the item of measurement used for it."},{"q":"Who do you think you are The Queen _____ England?","o":["to","for","at","of"],"a":3,"e":"noun *of* noun structure the King *of* Fools the Governor of Nevada"},{"q":"The teacher divided the candy _____ all the students of the class.","o":["between","with","to","among"],"a":3,"e":"Remember: *between* is for *two* things. *Among* is for more than *two*."},{"q":"He got _____ an argument with his neighbor.","o":["into","of","at","on"],"a":0,"e":"You can *get into* certain things: into trouble into an argument get into debt"},{"q":"Scissors are used _____ cutting paper.","o":["for","at","to","with"],"a":0,"e":"for -ing Something is used to cut Used (in order) to do something"},{"q":"My mother is the lady seated _____ the blue sofa in the corner.","o":["in","on","to","of"],"a":1,"e":"*In* a chair (with arms) *on* a chair (without arms) *on* a sofa (because it's wide and you might not be touching the arms of it)."},{"q":"What should I do _____ a sore throat?","o":["for","of","by","in"],"a":0,"e":"treatment You do something *for* a headache. Or *about* a *cold*."},{"q":"The paratroopers jumped out of the plane _____ hesitation.","o":["for","by","without","under"],"a":2,"e":"We do things either with or without hesitation."},{"q":"What I am asking _____ you is that you be quiet during other people's speeches.","o":["by","of","at","with"],"a":1,"e":"You *ask* something *of* someone. What I'm asking *of* you is that you do your homework."},{"q":"I found a great 3-bedroom apartment, so I'm going to move_____ base.","o":["away","off","toward","aboard"],"a":1,"e":"You either live *on* base or *off* base. So you would move *off* base."},{"q":"If he _____ speaking English, it's news to me. I thought he was speaking Icelandic.","o":["was","were","will","has"],"a":0,"e":"*Past real*. He really *was* speaking English."},{"q":"He stabbed his victim with a _____.","o":["rope","knife","gun","table"],"a":1,"e":"You would *stab* with a knife, not with the other 3 objects."},{"q":"Did you _____ a big breakfast this morning?","o":["ate","eats","eaten","eat"],"a":3,"e":"Anytime you use the *do*\" auxiliary, put simple form of the verb. *Do* you *go* to the gym every day? *Did* he *see* that movie?"},{"q":"No matter where you live, you need _____ access to a hospital.","o":["quickly","quick","quickness","quickest"],"a":1,"e":"\"Access\" is a noun. Modify it with an adjective. What kind of access? *Quick* access."},{"q":"Why is the baby crying? Because _____.","o":["he is hungry.","today is Saturday.","the car won't start.","the food was good."],"a":0,"e":"Of these four answers, the only thing to explain a baby's crying would be the *hunger*."},{"q":"Of my four brothers, Danny is _____.","o":["taller","the tallest","the taller","the tall"],"a":1,"e":"four people? Use the superlative. He is *the tallest* one of the four."},{"q":"He went down the hall _____.","o":["rapid","with rapid","very rapid","rapidly"],"a":3,"e":"We need an *adverb* ( -ly form) because it tells us *how* he went down the hall. Adverb of manner."},{"q":"I need _____ a car for the weekend.","o":["to rent","rent","renting","rented"],"a":0,"e":"The verb \"need\" requires the infinitive form in this structure."},{"q":"She is very _____.","o":["study","studious","student","studying"],"a":1,"e":"You need an adjective here. \"Studious\" is the adjective form of \"study."},{"q":"I didn't eat _____ yesterday.","o":["something","nothing","anything","none"],"a":2,"e":"double negatives! You must not say \"I didn't eat nothing.\""},{"q":"I made _____ mistakes on this test than I did on the one last week.","o":["few","fewer","less","lesser"],"a":1,"e":"fewer mistakes *mistakes* is a count noun. This is a comparative structure. I have *fewer* problems now than I did when I was a teenager."},{"q":"While _____ the street, be very careful to look in both directions.","o":["cross","crossing","crossed","being cross"],"a":1,"e":"This is a reduced structure: *while you are crossing the street* reduce it to *while crossing the street*."},{"q":"I want to tell you about some interesting _____ places you should visit when you come to my country.","o":["tourists","touristic","touristics","tourist"],"a":3,"e":"A place for tourists to visit is a tourist place. Don't use the word \"touristic."},{"q":"The witness avoided _____ the truth about his involvement in the robbery.","o":["to tell","tell","telling","the telling"],"a":2,"e":"Put the \" - ing\" form after \"avoid.\" He avoided *falling* because he grabbed a hold of the railing."},{"q":"The money _____ from the bank has not been recovered yet.","o":["steal","stealing","stole","stolen"],"a":3,"e":"This is a reduced clause structure. The money *which was stolen from the bank* can be reduced down to *the money stolen from the bank*."},{"q":"_____, the student left the testing room.","o":["Having finished","He finished","He was finish","After finish"],"a":0,"e":"Reduced clause. \"After he had finished\" can be reduced to the phrase \"Having finished."},{"q":"He *drowned*. He _____","o":["died in water.","fell off a mountain.","died in the dry desert.","was stabbed with a knife."],"a":0,"e":"*Drown* = to die by suffocation in liquid"},{"q":"Don't *gripe* so much.","o":["eat","complain","drink","buy thing spend money"],"a":1,"e":"*Gripe* = complain = say negative things = kvetch"},{"q":"I have _____ about question #2.","o":["a doubt","a root","a dude","a crunch"],"a":0,"e":"*A doubt* = an uncertainty = not knowing something"},{"q":"He is a *tightwad*. He is _____.","o":["ugly","stingy","argumentative","silly"],"a":1,"e":"*Tightwad* = stingy, miserly, doesn't want to spend his money. (Wants to keep all of his paper money rolled in a tight wad, without ever having to spend any of it.)"},{"q":"What is your opinion of this book? What do you _____?","o":["put it on","take it over","get across it","think of it"],"a":3,"e":"*To think of something* = to have an opinion. You just saw that new movie, didn't you? What did you think of it?"},{"q":"There are only 9 people _____ the bus right now.","o":["along","among","aboard","across"],"a":2,"e":"*Aboard* means to be on a large vehicle like a plane, bus, train, ship, space shuttle"},{"q":"There was a chemical spill in the *tail* of the jet. The spill was in the_____.","o":["rear","nose","wing","cockpit"],"a":0,"e":"tail = rear = aft = back part = (ship) stern"},{"q":"What is the *subject* of her speech?","o":["length","purpose","topic","source"],"a":2,"e":"subject = topic = what you are talking about"},{"q":"Craig looks very ill. He _____ go to the doctor right now!","o":["must to","is","have to","should"],"a":3,"e":"modals Should = advice If he's sick, he should go to the doctor."},{"q":"It is raining; _____, I want to play soccer outside.","o":["still","therefore","thus","furthermore"],"a":0,"e":"*Still* = but, yet, however *still* can be used for *contrast* structures"},{"q":"I am scheduled to take one more OPI, _____?","o":["am not I","aren't I","am I","are I"],"a":1,"e":"exception I AM, *aren't I*? More formal = I AM< *AM I not*?"},{"q":"My glass is empty. Please _____ again. I'm thirsty.","o":["wait on it","run it out","fill it up","chip it in"],"a":2,"e":"*Fill* up = replenish = put something in an empty space"},{"q":"Can we go _____ you to the movies?","o":["apart from","along with","due to","apart at"],"a":1,"e":"go along with = phrasal verb meaning to accompany"}]},{"id":"g_plus","sec":"Grammar","title":"Grammar Plus","desc":"Conditionals, passive, reported speech","items":[{"q":"If I _______ you, I would accept that assignment.","o":["were","was","am","be"],"a":0,"e":"Second conditional: 'If I were you' (subjunctive 'were' for all persons)."},{"q":"I go to _______ work by car every day.","o":["(no article)","the","a","an"],"a":0,"e":"No article in fixed expressions: go to work / go to bed."},{"q":"Look at the runway lights; they ______ on and off like that for the last ten minutes.","o":["have been flashing","are flashing","flashed","had flashed"],"a":0,"e":"'For the last ten minutes' + an action still happening now = present perfect continuous."},{"q":"When the new hangar finally opens next spring, the engineers ______ on it for almost three years.","o":["will have been working","will be working","have been working","would be working"],"a":0,"e":"Duration of an activity up to a future point: future perfect continuous."},{"q":"The new bridge *was to* open in May, but the opening was delayed until fall.","o":["was scheduled to","was used to","had to","used to"],"a":0,"e":"'Was to + verb' describes a past plan or schedule: it was scheduled to open."},{"q":"We ______ each other for only a few weeks when we got engaged, and our friends thought we were crazy.","o":["had known","have known","know","were knowing"],"a":0,"e":"Duration up to a past event (getting engaged): past perfect; 'know' is not used in continuous forms."},{"q":"If I had saved more money when I was single, I ______ about these car payments now.","o":["wouldn't be worrying","wouldn't have worried","won't be worrying","hadn't been worrying"],"a":0,"e":"Past condition + present result ('now'): would (not) be + -ing."},{"q":"The pilot checked the fuel twice. Only then ______ the engines.","o":["did she start","she started","she did start","started she"],"a":0,"e":"Only then at the start takes inversion with did + base verb: Only then did she start."},{"q":"That ______ Sergeant Kim at the door; she said she'd stop by around six.","o":["must be","must have","can be","should have been"],"a":0,"e":"must be: a confident present deduction; 'can' is not used for a specific deduction."},{"q":"It was the medic, not the doctor, ______ saved the soldier's life.","o":["who","which","whom","what"],"a":0,"e":"It-cleft for a person in subject position: It was ... who (or that) ..."},{"q":"Are you still afraid ______ flying after that rough landing?","o":["of","from","for","with"],"a":0,"e":"'Afraid of' + noun or -ing form: afraid of flying."},{"q":"If I ______ enough leave left this year, I would fly home for my sister's wedding, but I used it all in March.","o":["had","have","would have","would have had"],"a":0,"e":"Second conditional: an unreal present situation takes the past simple (had) in the if-clause."},{"q":"If the engineers had designed the network properly, we ______ these outages every single day now.","o":["wouldn't be having","wouldn't have been having","won't have","hadn't had"],"a":0,"e":"Mixed conditional: if + past perfect, would be + -ing for a present situation (now)."},{"q":"I wish the commander ______ a decision about the deployment dates soon; the whole unit is waiting.","o":["would make","makes","will make","has made"],"a":0,"e":"Wish + would + verb for a change we want someone else to make in the future."},{"q":"The pilots carry survival kits *in case* they have to eject over the ocean.","o":["because they might","on the condition that they","even though they","only after they"],"a":0,"e":"In case = as a precaution because something might happen."},{"q":"The new recruits ______ a thorough safety briefing by the range officer before the live-fire exercise.","o":["were given","gave","were giving","had given"],"a":0,"e":"Passive with two objects: the range officer gave the recruits a briefing -> the recruits were given a briefing."},{"q":"______ your teeth cleaned twice a year is fully covered by the military dental plan.","o":["Having","Have","Had","To having"],"a":0,"e":"Gerund subject with a causative: Having + object + past participle + singular verb (is)."},{"q":"The package was mailed on Monday, so it ______ here by Thursday at the latest.","o":["should be","should have","must have been","ought be"],"a":0,"e":"Should be: what we logically expect to be true (expectation, not obligation)."},{"q":"You ______ during the safety briefing instead of texting your girlfriend!","o":["should have been listening","must have been listening","should had been listening","should have listen"],"a":0,"e":"Should have been + -ing: criticism of what someone was (not) doing at a past time."},{"q":"At the end of the briefing, the colonel suggested ______ the exercise until the weather improved.","o":["postponing","to postpone","us to postpone","that we postponing"],"a":0,"e":"suggest + -ing (or suggest that we postpone); 'suggest someone to do' is wrong."},{"q":"I wonder ______ so quiet today; he usually never stops talking.","o":["why the sergeant is","why is the sergeant","why the sergeant does","why does the sergeant"],"a":0,"e":"After 'I wonder', use statement order: why the sergeant is so quiet."},{"q":"You'd rather stay on base this weekend than drive to the city, ______?","o":["wouldn't you","hadn't you","didn't you","don't you"],"a":0,"e":"'You'd rather' = you would rather, so the tag is 'wouldn't you?'."},{"q":"What ______ you do if your vehicle broke down in the middle of the desert?","o":["would","will","did","do"],"a":0,"e":"A hypothetical question with a past-tense if-clause uses 'would': What would you do if...?"},{"q":"The instructor asked for silence twice, but the two recruits in the back row just went on ______.","o":["whispering","to whisper","whisper","whispered"],"a":0,"e":"go on + -ing = continue doing the same thing; go on + to-infinitive = move on to something new."},{"q":"Sergeant Major Owens insisted on ______ every vehicle himself before the convoy left the gate.","o":["inspecting","to inspect","inspect","that inspect"],"a":0,"e":"insist on + -ing (insist is followed by the preposition 'on')."},{"q":"______ the instructor told us during the safety briefing turned out to be very useful.","o":["What","That","Which","Whose"],"a":0,"e":"What = the thing(s) that; the what-clause is the subject of the sentence."},{"q":"Lieutenant Brooks speaks ______ Arabic fluently because she spent most of her childhood in ______ Middle East.","o":["(no article) / the","the / (no article)","the / the","(no article) / (no article)"],"a":0,"e":"Languages take no article (speak Arabic); some regions always take 'the': the Middle East, the Midwest."},{"q":"Could you speak ______ more slowly? The connection on this line keeps breaking up.","o":["a little","little","a few","few"],"a":0,"e":"'A little' + comparative means 'slightly': a little more slowly, a little louder."},{"q":"He was promoted to staff sergeant ______ the age of twenty-four.","o":["at","in","on","with"],"a":0,"e":"We say 'at the age of + number' (or simply 'at twenty-four')."},{"q":"Private Grant was charged ______ assault after a fight in the parking lot of a bar.","o":["with","of","for","about"],"a":0,"e":"Charged WITH a crime (but accused OF a crime)."},{"q":"______ some soldiers like the early PT session, others find it very hard to get up at 0500.","o":["While","Despite","Therefore","However"],"a":0,"e":"While can mean 'whereas', contrasting two groups in the same sentence."},{"q":"Staff Sergeant Ruiz is one of the ______ in the whole maintenance company.","o":["best mechanics","better mechanics","best mechanic","most good mechanics"],"a":0,"e":"One of the + superlative + plural noun: one of the best mechanics."},{"q":"At no time ______ the classified documents out of her sight during the flight.","o":["did the courier let","the courier let","the courier did let","let the courier"],"a":0,"e":"At no time (= never) at the start causes inversion: did + subject + base form."},{"q":"The fog was ______ thick for the pilots to see the runway lights.","o":["too","so","such","enough"],"a":0,"e":"Too + adjective + for someone + to-infinitive; so would need a that-clause, and enough comes after the adjective."},{"q":"Sergeant Lopez *wasn't able to* finish the report before the deadline.","o":["couldn't","didn't want to","wasn't allowed to","didn't need to"],"a":0,"e":"Wasn't able to = couldn't (past ability), not a lack of permission or need."},{"q":"Everyone must ______ the safety video before using the new firing range.","o":["watch","watching","to watch","watched"],"a":0,"e":"After a modal verb (must, should, can) use the base form: must watch."},{"q":"Good afternoon, sir. ______ we leave our bags here while we check in?","o":["May","Are","Have","Does"],"a":0,"e":"Use May + subject + base verb to ask politely for permission."},{"q":"Corporal Brandt ______ on four different vehicles since he joined the transportation company.","o":["has qualified","qualified","have qualified","qualifies"],"a":0,"e":"Since + a starting point in the past needs the present perfect; with he, use has + past participle."},{"q":"My father ______ work the night shift at the airport, but now he has a regular day job.","o":["used to","uses to","is used to","was used"],"a":0,"e":"Used to + base verb = a past habit or situation that is no longer true."},{"q":"The bridge over the creek is so narrow that ______.","o":["only one truck can cross at a time","two trucks can cross at the same time","the creek is very deep in spring","drivers can park on both sides"],"a":0,"e":"So + adjective + that introduces a result: a very narrow bridge lets only one truck cross at a time."},{"q":"The number of foreign students at the language school ______ risen sharply since January.","o":["has","have","are","were"],"a":0,"e":"The number of + plural noun takes a singular verb, because the subject is the number: has risen."},{"q":"Travel to the island is permitted ______ that visitors carry a valid permit.","o":["provided","otherwise","although","nevertheless"],"a":0,"e":"Provided that = only if: travel is allowed on the condition that visitors carry a permit."},{"q":"The cat ______ the coffee table and landed on the sofa.","o":["jumped over","walked around","crawled under","looked at"],"a":0,"e":"Jump over = go up and across an obstacle; landed shows that the cat was in the air."},{"q":"Every visitor to the supply depot must wear a badge. The badge has to be visible at all times, even in the cafeteria, because guards check IDs without warning. According to the paragraph, visitors should ______.","o":["keep their badges in view","leave their badges at the gate","avoid eating in the cafeteria","ask the guards for a new badge each day"],"a":0,"e":"The badge must be visible at all times, so visitors should keep it in view."},{"q":"A soldier who has a fractured wrist should ______.","o":["get an X-ray at the clinic","carry a heavy pack as usual","lift weights with that hand","ignore it and keep training"],"a":0,"e":"A fractured wrist is a broken bone, so the soldier needs an X-ray and treatment at the clinic."},{"q":"The old tent had so many holes that it was no longer ______, so we ordered a new one.","o":["usable","visible","portable","fashionable"],"a":0,"e":"Usable = able to be used; a tent with many holes can no longer be used."},{"q":"The news that the field exercise has been canceled is ______ to most of the trainees.","o":["disappointing","disappointed","disappoint","disappointment"],"a":0,"e":"Use the -ing adjective for the thing that causes the feeling: the news is disappointing."},{"q":"Hurry, Corporal! How ______ time do we have before the briefing starts?","o":["much","many","few","a lot"],"a":0,"e":"Time is uncountable, so ask How much time...?"},{"q":"Owls hunt mostly at night. Their large eyes gather even the faintest light, and their soft feathers let them fly almost without a sound. According to this paragraph, owls ______.","o":["can hunt without being heard","usually sleep during the night","have trouble seeing in the dark","hunt mainly in noisy forests"],"a":0,"e":"Soft feathers let owls fly almost without a sound, so they can hunt without being heard."},{"q":"Private Novak stuffed ______ that he could not zip it.","o":["so many clothes into his bag","clothes so many into his bag","so clothes many into his bag","many so clothes into his bag"],"a":0,"e":"Word order: so + many/much + noun, then the place phrase (so many clothes into his bag)."}]},{"id":"g_topics","sec":"Grammar","title":"Grammar by topic","desc":"Prepositions, tenses, modals and more","items":[{"q":"The convoy ______ the checkpoint when the ambush started.","o":["approaches","was approaching","has approached","approach"],"a":1,"e":"An action in progress that is interrupted takes the past progressive.","t":"Tenses"},{"q":"This time next week we ______ across the Mediterranean.","o":["sail","will sail","will be sailing","have sailed"],"a":2,"e":"An action in progress at a future moment.","t":"Tenses"},{"q":"At 8 o'clock yesterday evening we ______ the frigate.","o":["inspect","inspected","were inspecting","have inspected"],"a":2,"e":"A precise past time with an action in progress.","t":"Tenses"},{"q":"The patrol ______ back before dark yesterday.","o":["comes","came","has come","will come"],"a":1,"e":"*Yesterday* is a finished time in the past: simple past, *came*.","t":"Tenses"},{"q":"We _____ to my brother's house tomorrow.","o":["will go","are go","went","have gone"],"a":0,"e":"The time word \"tomorrow\" needs *future tense*.","t":"Tenses"},{"q":"The color red on the flag _____ blood.","o":["symbolizing the","symbolize","is symbolize","symbolizes"],"a":3,"e":"*The color* is singular (*it*), so the present simple takes -s: *symbolizes*.","t":"Tenses"},{"q":"Yesterday, I _____ tardy for class because my car wouldn't start.","o":["was","were","will be","am"],"a":0,"e":"yesterday = past tense Yesterday *I was*","t":"Tenses"},{"q":"I haven't seen my family _____ October 23.","o":["until","from","since","for"],"a":2,"e":"When you give only the starting point of measuring the time, use \"since\" in these October 25.","t":"Tenses"},{"q":"By the time you graduate, you _____ at least 40 tests.","o":["took","will be taking","will have taken","would have taken"],"a":2,"e":"future perfect tense By the time I retire, I will have worked for this company for 35 years.","t":"Tenses"},{"q":"You ______ salute a senior officer; it is a regulation.","o":["might","must","could","may"],"a":1,"e":"An absolute obligation, such as a regulation: must.","t":"Modals"},{"q":"You ______ better check the coordinates twice.","o":["would","had","should","must"],"a":1,"e":"had better + the simple form of the verb (had better check).","t":"Modals"},{"q":"If you are tired, you _____.","o":["would rest","must to rest","should rest","would have rest"],"a":2,"e":"Advice. \"Should\" is a common modal when giving advice. If these questions are too easy, you *should go* to a higher level.","t":"Modals"},{"q":"I hear a lot of police sirens. Someone _____ have committed a crime nearby.","o":["must","should","would rather","shall"],"a":0,"e":"*Inference modal* Based on some evidence, you come to a logical conclusion.","t":"Modals"},{"q":"She _____ the message; her phone was switched off all day.","o":["mustn't receive","can't have received","shouldn't receive","mustn't be receiving"],"a":1,"e":"Deduction that a past event was impossible: *can't have* + past participle.","t":"Modals"},{"q":"This bridge ______ in 1952.","o":["is built","was built","has built","built"],"a":1,"e":"A date in the past: past passive, was built.","t":"Passive"},{"q":"I had the secretary _____ the letter five times before I was satisfied.","o":["retyping","retypes","retype","retyped"],"a":2,"e":"You have a person DO something, simple form of the verb.","t":"Passive"},{"q":"These drugs must be given top the patients under _____ conditions.","o":["control","controlled","controlling","controls"],"a":1,"e":"passive voice structure The conditions are controlled by someone, so they are *controlled* conditions.","t":"Passive"},{"q":"The package _____ today. Otherwise, it won't get there for my mother's birthday.","o":["must be mailing","must mail","will be mail","must be mailed"],"a":3,"e":"Passive voice is requited here. *Must be mailed*.","t":"Passive"},{"q":"The files _____ when the power failed.","o":["were being copied","are copied","have been copied","copy"],"a":0,"e":"Past continuous passive: *was/were being* + past participle.","t":"Passive"},{"q":"If that thief hadn't tricked me, I ______ in prison now.","o":["wouldn't be","wouldn't have been","won't be","am not"],"a":0,"e":"Mixed conditional: past condition, present result.","t":"Conditionals"},{"q":"If only I ______ listened to your advice!","o":["have","had","would","did"],"a":1,"e":"If only + past perfect expresses regret about the past.","t":"Conditionals"},{"q":"If I were a person who _____ a million dollars, I would retire immediately.","o":["has","have","have had","had"],"a":3,"e":"The unreal part is having a million dollars, so the verb after *who* is in the past too: if I were a person who *had* a million dollars, I would retire.","t":"Conditionals"},{"q":"I wish I _____ the contract without reading it.","o":["did not sign","had not signed","would not sign","was not signed"],"a":1,"e":"*Wish* + past perfect expresses regret about a past action.","t":"Conditionals"},{"q":"\"Do you like tea?\" -> He asked her ______ she liked tea.","o":["that","if","what","which"],"a":1,"e":"A yes/no question is reported with if or whether.","t":"Reported speech"},{"q":"\"Water boils at 100 C,\" he said. -> He said water ______ at 100 C.","o":["boiled","boils","had boiled","would boil"],"a":1,"e":"A general truth does not change tense in reported speech.","t":"Reported speech"},{"q":"Last week, he promised me that he _____ attend yesterday's meeting.","o":["will","was going","did","would"],"a":3,"e":"Reported speech: the reporting verb *promised* is in the past, so *will* becomes *would*.","t":"Reported speech"},{"q":"He has been in the Navy ______ 2008.","o":["for","since","from","during"],"a":1,"e":"since + a starting point in time (since 2008); for + a length of time (for six years).","t":"Prepositions"},{"q":"We always *store* our sweaters and coats during the summer.","o":["take off","put away","throw out","keep on"],"a":1,"e":"*Store* = put away, put in storage, put out-of-sight, maybe in the closet or in a trunk","t":"Prepositions"},{"q":"A pecking order is an organization is _____.","o":["a tapestry","a deflation","a jowl","a hierarchy"],"a":3,"e":"pecking order = in the barnyard, the bigger powerful birds \"peck\" on the smaller her place.","t":"Prepositions"},{"q":"When the alarm went off, the soldiers ______.","o":["sleep","were sleeping","are sleeping","sleeping"],"a":1,"e":"An action in progress (*were sleeping*) interrupted by a short action in the simple past (*went off*).","t":"Prepositions"},{"q":"The Sears Tower is the tallest building _____ Chicago.","o":["to","in","by","at"],"a":1,"e":"In the world In space In your imagination In the universe","t":"Prepositions"},{"q":"Don't sit with your elbows _____ the table.","o":["for","in","on","with"],"a":2,"e":"touching the surface only *on* the table","t":"Prepositions"},{"q":"Cats like to sleep all day and prowl the neighborhoods _____ night.","o":["in","during","at","on"],"a":2,"e":"in the morning in the afternoon in the evening *but* at night","t":"Prepositions"},{"q":"Turn right _____ the next intersection.","o":["on","at","to","for"],"a":1,"e":"place *turn at* the sign *turn at* the traffic light.","t":"Prepositions"},{"q":"The contractors are going to tear _____ the old road and replace it with a modern 4-lane one.","o":["down","up","over","off"],"a":1,"e":"The road is lying flat *on* the ground, so you have to tear it *up*.","t":"Prepositions"},{"q":"Craig looks *down in the dumps* today.","o":["rich","unhappy","talented","angry"],"a":1,"e":"*Down in the dumps* = unhappy = sad = dejected = in a depressing situation, as if one is *living in the dump*.","t":"Prepositions"},{"q":"My favorite season of the year is *autumn*.","o":["winter","spring","summer","fall"],"a":3,"e":"seasons of the year *fall* = *autumn* (September, October, November in the U.S.)","t":"Prepositions"},{"q":"Blake is 17 years old. Neil is 18 years old. Craig is 16 years old.","o":["Neil is younger than Blake.","Blake is older than Neil.","Craig is younger than Neil.","Craig is older than Blake."],"a":2,"e":"Craig (16) is younger than Neil (18). Neil is the oldest and Craig is the youngest.","t":"Prepositions"},{"q":"It is not polite to stare _____ strangers.","o":["for","with","at","on"],"a":2,"e":"*Stare at*, *look at*, *point at*: these verbs take *at* before the person or thing.","t":"Prepositions"},{"q":"I visited my family _____ Christmas.","o":["in","to","of","for"],"a":3,"e":"preposition of time *for* a short period of *time*.","t":"Prepositions"},{"q":"Nadia has worked at the hospital ever _____ she graduated.","o":["from","when","since","ago"],"a":2,"e":"*Ever since* links a present situation to its starting point in the past.","t":"Prepositions"},{"q":"We have ______ time before the briefing.","o":["a few","few","little","many"],"a":2,"e":"time is uncountable with a negative sense, so little.","t":"Determiners"},{"q":"______ information you gave me was very useful.","o":["A","An","The","-"],"a":2,"e":"Something already known (a definite reference) takes the.","t":"Determiners"},{"q":"This frigate is ______ than the previous one.","o":["more fast","faster","fastest","the fastest"],"a":1,"e":"Short adjective, so the comparative takes -er.","t":"Structure"},{"q":"Let's not _____ the decision until we have the full report.","o":["taking","to take","taken","take"],"a":3,"e":"The negative form is *let's not* + base form.","t":"Structure"},{"q":"This is _____ route to the airport at this hour.","o":["fast","faster","the fastest","the most fast"],"a":2,"e":"Short adjectives form the superlative with *-est*: the fastest.","t":"Structure"},{"q":"_____ he had trained for months, he failed the swimming test.","o":["Despite","Even though","In spite","Therefore"],"a":1,"e":"Only *even though* can introduce a subject and a conjugated verb.","t":"Structure"},{"q":"The committee demanded that the report _____ immediately.","o":["is published","publishes","be published","has been published"],"a":2,"e":"The subjunctive passive is *be* + past participle: that it be published.","t":"Structure"},{"q":"I do not remember _____ that decision. When was it made?","o":["to make","making","I had made","we are making"],"a":1,"e":"*Remember* + -ing refers to a memory of something already done. With the infinitive it would mean not forgetting to do it.","t":"Structure"},{"q":"My sister ______ in Milan for two months last year.","o":["is","was","had","did"],"a":1,"e":"last year + a state (be): simple past, was.","t":"Simple past"}]},{"id":"v_ctx","sec":"Vocabulary","title":"Vocabulary in context","desc":"Words and their meaning in a sentence","items":[{"q":"We found a *flaw* in the structural design.","o":["insect","error","tool","change"],"a":1,"e":"*A flaw* is a mistake, error, something wrong."},{"q":"You must keep the *aisle* clear.","o":["surface","walkway","sofa","fence"],"a":1,"e":"An *aisle* is a long narrow space between chairs, usually in a theater, in a church, in an auditorium"},{"q":"The floor is covered with *splinters*.","o":["water","dead flowers","spilled food","small pieces of wood"],"a":3,"e":"*Spinters* are very small pieces of wood, created when you are whittling, sawing, chopping"},{"q":"Here's some news. It's hot off the press.","o":["It's incorrect.","It's the most recent.","It's unbelievable.","It's funny."],"a":1,"e":"News that is hot off the press has just been printed and often contains the most recent information about something."},{"q":"The boss sent me off on some wild goose chase.","o":["I was given a great assignment.","I was given an impossible task.","I was given a promotion and a raise.","I was given extra help with my job."],"a":1,"e":"wild-goose chase / a search which is completely unsuccessful and a waste of time because the person or thing being searched for does not exist or is somewhere else"},{"q":"How old is your father?","o":["He has 67 years.","He is being 67 years.","He is 67.","He does 67."],"a":2,"e":"In English, we do our ages with the *be* verb, not the *have* verb. My car *is* four years when she died."},{"q":"Her testimony corroborated the earlier statement.","o":["confirmed","contradicted","replaced","questioned"],"a":0,"e":"Corroborate = confirm with further evidence."},{"q":"The negotiations reached a deadlock.","o":["a standstill","an agreement","a conclusion","a compromise"],"a":0,"e":"Deadlock = a situation in which no progress is possible."},{"q":"The regulation supersedes all previous versions.","o":["replaces","confirms","completes","cancels partly"],"a":0,"e":"Supersede = replace an older rule or version."},{"q":"Their cooperation has been invaluable.","o":["extremely useful","worthless","occasional","expected"],"a":0,"e":"Invaluable = extremely useful. Careful, it does not mean without value."},{"q":"Because of the heavy rain, we will have to *cancel* the parade.","o":["call off","put off","delay","postpone"],"a":0,"e":"cancel = call off ((postpone = put off))"},{"q":"The milk tastes *sour*.","o":["unpleasant","delicious","sweet","good"],"a":0,"e":"sour = bad = not good = gone bad (for milk) *sour* (for lemon or lime) means *tart*, *tangy*, \"attacks\" the tongue"},{"q":"*I rarely* go to movies during the weekend.","o":["seldom","usually","from time to time","often"],"a":0,"e":"*Rarely* = *seldom*, not very often, only once in a blue moon"},{"q":"I _____ a new car last week.","o":["buy","bought","buyed","was buy"],"a":1,"e":"Time words \"last week\" require *past tense*."},{"q":"If the food is rotten, what should you probably do to it?","o":["Eat it.","Serve it.","Save it.","Throw it out."],"a":3,"e":"rotten = spoiled = not good = probably cannot be eaten"},{"q":"Children should not play near the dump with *bare* feet.","o":["naked","unwashed","healthy","two"],"a":0,"e":"bare = naked = not covered with clothing = exposed"},{"q":"There was a *blizzard* last night.","o":["light shower","heavy snowstorm","raging flood","mild breeze"],"a":1,"e":"blizzard = a lot of snow driven by strong winds"},{"q":"We *spotted* the enemy sniper at a sixteenth-floor window.","o":["detected","drew","shot","sent"],"a":0,"e":"*To spot* = to see, to detect, to discern at a distance"},{"q":"The police found a corpse behind the Bellamy Theater.","o":["killer","dead person","military person","vehicle"],"a":1,"e":"*Corpse* = dead person, body (dead body)"},{"q":"He gave a *dazzling* speech.","o":["brilliant","hideous","very bad","prolonged"],"a":0,"e":"dazzling = brilliant = impressive = extremely good = great"},{"q":"We need to *boost* morale around here.","o":["measure","lower","raise","evaluate"],"a":2,"e":"boost = raise = increase A booster rocket a booster shot I can't reach the highest shelf. Give me a *boost*."},{"q":"I got *drenched* last night as I was walking home from the movies.","o":["soaked","lost","dizzy","lonely"],"a":0,"e":"*Drenched* means very wet; to make someone or something extremely wet"},{"q":"He was very sick; *therefore*, he couldn't compete in the race.","o":["yet","however","since","thus"],"a":3,"e":"*Therefore* = *thus*, so, as a result, because of this, consequently"},{"q":"Some of these questions are *bewildering*.","o":["easy","amusing","long","confusing"],"a":3,"e":"bewildering = confusing = not easy to understand"},{"q":"There was a typical *snafu* about the out processing schedules.","o":["success","good arrangement","problem","routine"],"a":2,"e":"snafu = typical problem = acronym for \"Situation Normal : All Fouled Up.\" *S-n-a-f- u*."},{"q":"Don't drag your feet.","o":["Don't hurry.","Don't run.","Don't stumble.","Don't delay."],"a":3,"e":"to drag your feet = to delay = to do something slowly"},{"q":"He is not telling the truth.","o":["He is jogging.","He is starving.","He is lying.","He is working."],"a":2,"e":"to lie = to *not* tell the truth = to say untrue things"},{"q":"That is a *confusing* math problem.","o":["easy","perplexing","boring","simple"],"a":1,"e":"confusing = perplexing = hard to understand = difficult to decipher"},{"q":"She brought up an important point during the meeting. “Bring up” means:","o":["mention / raise","criticize","reject","write down"],"a":0,"e":"Bring up = mention a topic (also: raise a child)."},{"q":"He made up an excuse for being late. “Make up” here means:","o":["invent","accept","repeat","apologize"],"a":0,"e":"Make up = invent (a story, an excuse); also: reconcile."},{"q":"Fighting broke out near the border at dawn. “Break out” means:","o":["start suddenly","stop completely","move south","calm down"],"a":0,"e":"Break out = begin suddenly (war, fire, epidemic)."},{"q":"He really takes after his father. “Take after” means:","o":["resemble (a parent)","obey","follow physically","admire"],"a":0,"e":"Take after = look or behave like an older family member."},{"q":"Please draw up a new plan. “Draw up” means:","o":["prepare in writing","cancel","shorten","approve"],"a":0,"e":"Draw up = prepare in writing (a plan, a report, a contract)."},{"q":"Report to the supervisor *promptly*.","o":["right away","when you feel like it","eventually","as late as you like"],"a":0,"e":"promptly = right away = quickly = as soon as possible = without delay"},{"q":"That new sonar system cost an arm and a leg. It was:","o":["extremely expensive","slightly damaged","bought on credit","a bargain"],"a":0,"e":"Cost an arm and a leg = be very expensive."},{"q":"The protest got out of hand very quickly. It:","o":["became impossible to control","ended peacefully","was well organized","was postponed"],"a":0,"e":"Get out of hand = become uncontrollable."},{"q":"We passed the inspection by the skin of our teeth. That is:","o":["only just / barely","with an excellent score","thanks to the dentist","without any effort"],"a":0,"e":"By the skin of your teeth = by a very narrow margin."},{"q":"The transfer order came out of the blue. It was:","o":["completely unexpected","sent by the navy","delayed","predictable"],"a":0,"e":"Out of the blue = suddenly, without warning."},{"q":"Skip the details and cut to the chase. “Cut to the chase” means:","o":["get to the main point","end the meeting","start running","lower your voice"],"a":0,"e":"Cut to the chase = go directly to the essential point."},{"q":"Give me a ballpark figure for the repair costs. This means:","o":["a rough estimate","an exact amount","the maximum price","a written invoice"],"a":0,"e":"Ballpark figure = approximate number (from baseball)."},{"q":"It took the new ensign a month to learn the ropes. This means:","o":["learn how the job is done","study knots only","get physically fit","memorize the ranks"],"a":0,"e":"Learn the ropes = learn the basics of a job (nautical origin)."},{"q":"The president hesitated to put boots on the ground. This means:","o":["deploy ground troops","buy new equipment","inspect the barracks","order new uniforms"],"a":0,"e":"Boots on the ground = soldiers physically deployed in an area."},{"q":"He was left holding the bag. This means:","o":["he took the blame alone","he received a reward","he was promoted","he resigned"],"a":0,"e":"Be left holding the bag = be left to take the blame alone."},{"q":"The talks hit a snag. This means:","o":["met an unexpected problem","ended successfully","were cancelled","were rushed"],"a":0,"e":"Hit a snag = meet an unexpected problem."},{"q":"Excessive noise is _____ to concentration.","o":["responsible","harmful","incredible","efficient"],"a":1,"e":"*Harmful to* means damaging to something."},{"q":"Please _____ that all the windows are closed before you leave.","o":["affect","undergo","ensure","maintain"],"a":2,"e":"*Ensure that* means make certain that. *Undergo* means to experience."},{"q":"The witness could not give an _____ account of the incident.","o":["capable","accurate","conscious","prior"],"a":1,"e":"*Accurate* means exact and free from error. *Prior* means earlier."},{"q":"The course is designed to help officers _____ their leadership skills.","o":["grow","spread","develop","stretch"],"a":2,"e":"Skills are *developed*. *Grow* and *stretch* are not used with abilities acquired through training."},{"q":"On whose _____ was the door opened?","o":["majority","superiority","authority","inferiority"],"a":2,"e":"*On whose authority* asks who gave the order or the right to act."},{"q":"Fatigue is one of the lasting _____ of the illness.","o":["delay effects","over effects","after effects","down effects"],"a":2,"e":"*After-effects* are the effects that remain once the cause has passed."}]},{"id":"v_mil","sec":"Vocabulary","title":"American & military","desc":"Words of everyday and military life","items":[{"q":"The platoon conducted a reconnaissance mission near the border. “Reconnaissance” means:","o":["exploration to gather information","a direct assault","a supply delivery","a training drill"],"a":0,"e":"Reconnaissance = observing an area to collect intelligence (recon)."},{"q":"They reinforced the position overnight. “Reinforced” means:","o":["strengthened with additional troops or material","abandoned quickly","photographed","surrounded"],"a":0,"e":"To reinforce = to make stronger with extra forces or support."},{"q":"The store is two blocks away. A “block” is:","o":["a section of street between two intersections","a large building","a bus stop","a kilometer"],"a":0,"e":"Block = the distance between two street corners."},{"q":"A “no-fly zone” is:","o":["airspace where flights are prohibited","a radar blind spot","an airport","a training area"],"a":0,"e":"No-fly zone = airspace where flights are prohibited."},{"q":"A colonel ______ a major, so the major salutes first when they meet outdoors.","o":["outranks","outnumbers","outgrows","overtakes"],"a":0,"e":"To outrank = to hold a higher rank than someone. A colonel is above both a lieutenant colonel and a major."},{"q":"The *sentry* at the fuel point stopped the truck and asked the driver for the password.","o":["a soldier on guard duty","a traffic controller","a supply clerk","a civilian receptionist"],"a":0,"e":"A sentry is a soldier posted to keep watch and control who passes; a common synonym is 'guard'."},{"q":"The ship took on fresh *provisions* in Naples before sailing east for six weeks at sea.","o":["supplies of food and water","conditions written into a contract","new crew members","spare engine parts"],"a":0,"e":"Provisions (plural) = supplies of food and drink, especially for a journey. In a contract, a provision is a condition."},{"q":"The fuel trucks are ______ route to the airfield and should arrive within the hour.","o":["en","in","on","at"],"a":0,"e":"En route (from French) = on the way. 'On route' is a common mistake."},{"q":"The two patrols left by different routes and will *rendezvous* at the old bridge at 2200.","o":["meet as previously arranged","set up a defensive position","wait for further orders","cross the river together"],"a":0,"e":"To rendezvous (RON-day-voo) = to meet at a time and place agreed in advance."},{"q":"*Chow* will be served in the field at 1800, so bring your mess kit.","o":["food; a meal","hot coffee","the daily briefing","the mail"],"a":0,"e":"Chow is informal American (especially military) English for food or a meal; the dining facility is often called the chow hall."},{"q":"During the ______ exercise, Marines came ashore from the ships in landing craft.","o":["amphibious","ambiguous","ambitious","anonymous"],"a":0,"e":"Amphibious operations move forces from the sea onto land."},{"q":"The platoon stood in ______ for twenty minutes while the inspector checked every uniform.","o":["formation","information","formality","format"],"a":0,"e":"In formation = arranged in ranks and lines, as soldiers stand for inspection or announcements."},{"q":"The rent is $1,200 a month, but *utilities* are extra, so budget another $200 for them.","o":["electricity, water and gas services","furniture and kitchen appliances","repairs and maintenance done by the owner","local property and parking taxes"],"a":0,"e":"Utilities = basic services for a home, such as electricity, water, gas and sometimes internet."},{"q":"The carpet is covered with dog hair, so please ______ it before our guests arrive.","o":["vacuum","mop","polish","iron"],"a":0,"e":"Vacuum (US verb) = clean with a vacuum cleaner (UK also 'hoover'); you mop hard floors, not carpets."},{"q":"He wore a gray suit with a matching *vest* and a red tie to the wedding.","o":["a sleeveless jacket worn over a shirt","a cotton undershirt worn under a shirt","a scarf tied loosely around the neck","a wide belt worn around the waist"],"a":0,"e":"Vest (US) = a sleeveless garment worn over a shirt, often part of a suit (UK: waistcoat). A British 'vest' is an undershirt."},{"q":"The salary isn't great, but the ______ are excellent: health insurance, a pension plan and three weeks of paid leave.","o":["benefits","wages","profits","duties"],"a":0,"e":"Benefits are what a job gives you in addition to pay, such as health insurance and paid leave."},{"q":"There's been an accident at the ______ of Main Street and Fifth Avenue, so traffic is backed up.","o":["intersection","overpass","sidewalk","median"],"a":0,"e":"An intersection is the place where two or more streets cross (UK: junction / crossroads)."},{"q":"After flying from Kuwait to Texas, I had terrible ______ and kept waking up at 3 a.m. for a week.","o":["jet lag","seasickness","heatstroke","frostbite"],"a":0,"e":"Jet lag is tiredness and disturbed sleep after flying across several time zones."},{"q":"Stay home until your fever is gone; the flu is highly ______ in the first few days.","o":["contagious","curable","painless","harmless"],"a":0,"e":"Contagious = easily passed from one person to another, which is why you should stay home."},{"q":"The trucking company plans to ______ fifty new drivers before the holiday season.","o":["hire","rent","lease","borrow"],"a":0,"e":"In American English you hire people but rent or lease cars and apartments."},{"q":"Before deploying, every soldier is encouraged to ______ a will and update the beneficiaries on their life insurance.","o":["make","take","give","pay"],"a":0,"e":"make a will = prepare the legal document that says who receives your property."},{"q":"Service members should ______ advantage of the free tuition assistance program while they're still on active duty.","o":["take","make","have","get"],"a":0,"e":"take advantage of = make good use of an opportunity."},{"q":"Sergeant, can I ______ a word with you after formation? It's about your leave request.","o":["have","make","take","do"],"a":0,"e":"have a word with someone = speak to someone briefly, often in private."},{"q":"The city ______ tribute to the firefighters who lost their lives in the warehouse fire.","o":["paid","made","did","took"],"a":0,"e":"pay tribute to = publicly show respect and admiration for."},{"q":"Try to *catch the waiter's eye* so we can ask for the check.","o":["get the waiter's attention","look at the waiter angrily","avoid looking at the waiter","call the waiter by name"],"a":0,"e":"catch someone's eye = attract someone's attention."},{"q":"A ______ diet and regular exercise will help you pass the physical fitness test.","o":["balanced","equal","even","fair"],"a":0,"e":"a balanced diet = the right amounts of different kinds of food."},{"q":"After an ______ 20-mile march, the recruits fell asleep the moment they reached camp.","o":["exhausting","exhausted","exhaustion","exhaust"],"a":0,"e":"An -ing adjective describes what causes the feeling (the march); -ed describes how people feel (the recruits were exhausted)."},{"q":"Applicants should ______ have some experience with satellite communications.","o":["preferably","preferable","preference","preferred"],"a":0,"e":"Preferably (adverb) = if possible; it goes between 'should' and the main verb."},{"q":"______, the inspection has been moved to Thursday, but nobody has told the first sergeant yet.","o":["Apparently","Apparent","Appearance","Appeared"],"a":0,"e":"A sentence adverb is needed at the start: apparently (= it seems, according to what people say)."},{"q":"Months of careful ______ went into the joint exercise with our allies.","o":["preparation","prepared","preparatory","prepare"],"a":0,"e":"'Months of careful ___' needs a noun: preparation."},{"q":"At lunch, soldiers have a ______ between a hot meal and a boxed sandwich.","o":["choice","choose","chose","chosen"],"a":0,"e":"'have a ___ between' needs a noun: choice. Choose / chose / chosen are verb forms."},{"q":"From the mud on his boots, it was ______ that he had just come in from the field.","o":["evident","evidence","evidently","evidences"],"a":0,"e":"'It was evident that' = it was clear that. Evidence is the noun."},{"q":"In his farewell speech, the general thanked his staff for their ______ during a difficult year.","o":["loyalty","loyal","loyally","disloyal"],"a":0,"e":"'their ___' needs a noun: loyalty. Loyal is the adjective."},{"q":"Throughout the course, the instructors placed great ______ on weapon safety.","o":["emphasis","emphasize","emphatic","emphatically"],"a":0,"e":"'place emphasis on' uses the noun emphasis; emphasize is the verb."},{"q":"It took the recruits from Alaska several weeks to ______ to the summer heat in Texas.","o":["adapt","adopt","adept","adaptive"],"a":0,"e":"Adapt to = change to suit new conditions; adopt = start to use a plan or idea, or take a child into your family; adept = skilled."},{"q":"The delay in this month's pay statements was *attributed to* a software error at the finance office.","o":["explained as caused by","made much worse by","first noticed because of","kept secret because of"],"a":0,"e":"Attribute something to = say or believe that it is the result of something."},{"q":"Several new problems *emerged* during the second week of testing the software.","o":["appeared or became known","were finally solved","were deliberately hidden","slowly disappeared"],"a":0,"e":"Emerge = appear or become known, especially after being hidden."},{"q":"The higher cost of the new boots is *offset* by the fact that they last twice as long.","o":["balanced out","made worse","partly explained","kept hidden"],"a":0,"e":"Offset = balance one thing against another so that its effect is reduced or canceled."},{"q":"The first test was canceled, but all *subsequent* tests were completed without any problems.","o":["later","earlier","shorter","similar"],"a":0,"e":"Subsequent = coming after something else; later."},{"q":"Because of the computer outage, the finance office now has a *backlog* of 300 travel claims.","o":["pile of unprocessed work","list of rejected requests","stock of backup copies","record of past payments"],"a":0,"e":"Backlog = an amount of work that should already have been done and is still waiting."},{"q":"The workshop gave us real *insight* into how the logistics system actually works.","o":["understanding","practical training","direct access","official authority"],"a":0,"e":"Insight into something = a clear, deep understanding of it."},{"q":"The new commander promised a more *transparent* process for approving leave requests.","o":["open and honest","able to be seen through","faster and simpler","strict and formal"],"a":0,"e":"Transparent (of a process) = open and honest, so people can see how decisions are made."},{"q":"Seaman Ortiz may eat only soft foods this week because of his dental surgery. For lunch, he can have ______.","o":["mashed potatoes","a crunchy apple","hard pretzels","crusty bread rolls"],"a":0,"e":"Soft foods are easy to chew, like mashed potatoes; a crunchy apple, pretzels and crusty bread are hard."},{"q":"After the dry summer, the base *cut* its water use by almost a third.","o":["reduced","doubled","measured","wasted"],"a":0,"e":"Cut here means reduced, made smaller in amount."},{"q":"A nurse *administered* the flu shots to the whole company in less than an hour.","o":["gave","refused","ordered","counted"],"a":0,"e":"Administer a shot, a test or a medicine = give it."},{"q":"Which item below is a fastener? ______","o":["a screw","a ladder","a funnel","a bucket"],"a":0,"e":"A fastener holds two things together; a screw, like a nail or a bolt, is a fastener."},{"q":"A thick accumulation of dust covered the old radio in the storeroom. What covered the radio? ______","o":["a thick layer of dust","a few drops of oil","a wet piece of cloth","a sheet of plastic"],"a":0,"e":"An accumulation is a gradual build-up of something, so an accumulation of dust is a thick layer of dust."},{"q":"Heavy snow fell *throughout* the night, and the roads were closed by morning.","o":["during all of","at the start of","at the end of","long after"],"a":0,"e":"Throughout = during the whole of a period of time."},{"q":"Thanks for the invitation to the barbecue, Sergeant, but I won't be able to *make it*. This means the speaker ______.","o":["cannot come","will cook","will arrive early","was not invited"],"a":0,"e":"Make it = be able to come; \"can't make it\" means \"cannot attend\"."},{"q":"The late snowstorm caused *considerable* delays at the airport, and some passengers waited more than ten hours.","o":["large","slight","polite","sudden"],"a":0,"e":"Considerable = large in size or amount: considerable delays means long delays."}]},{"id":"i_idm","sec":"Idioms","title":"American idioms","desc":"Common expressions and their meaning","items":[{"q":"Someone else volunteered for the extra duty. You're *off the hook*.","o":["guilty","free of responsibility","in charge of everything","expected to work harder"],"a":1,"e":"free If a fish is hooked, he is in big trouble. If the fish is *off the hook*, he has managed to escape and he is now free."},{"q":"Athletes who want to be bouncers in clubs and bars are *a dime a dozen*.","o":["expensive to hire","not very smart","very common","rare and desirable"],"a":2,"e":"be a dime a dozen *us* ( *UK also* be two/ten a penny ) to be common and/or of very little value . Books like this are a dime a dozen."},{"q":"I think this is *a red herring*.","o":["a false clue","a funny joke or story","a big disaster","a correct answer"],"a":0,"e":"ˌred herring: a fact, idea or subject that takes people's attention away from the central our attention away from the truth."},{"q":"The unit operates _______ the direct control of the joint headquarters.","o":["under","below","beneath","down"],"a":0,"e":"'Under the control/command of' is the fixed expression."},{"q":"My uncle deals in *real estate*.","o":["minerals","land and property","stocks and bonds","farm animals"],"a":1,"e":"*Real estate* = land and property, buildings"},{"q":"Let's *stop working on* this exercise for a minute and do something different.","o":["look after","come across","drop out of","put aside"],"a":3,"e":"*Put aside* = move something to the side and not work with it for a while"},{"q":"I can't go to the movies with you. I have to *burn the midnight oil*.","o":["sleep all night","work late at night","watch TV all night","make a 12:00 phone call"],"a":1,"e":"*Burn the midnight oil* = work or study late into the night."},{"q":"My neighbor drives *like a bat out of hell*.","o":["slowly","carefully","very fast","considerately"],"a":2,"e":"*A bat out of hell*= fast, wild, crazy, dangerous"},{"q":"He's *plying a new trade* these days.","o":["He has a different job.","He has remarried.","He is driving a new car.","He is living in a different home."],"a":0,"e":"A *trade* = a job. To *ply a trade* = to work at a job."},{"q":"I made a *serious error* on the math test.","o":["great score","big mistake","small correction","minor problem"],"a":1,"e":"error = mistake = wrong answer serious = big = major"},{"q":"*I sent for* Mariah Carey's new CD.","o":["loaned out","borrowed","ordered by mail","threw out"],"a":2,"e":"*Send for* = to order something through the mail system"},{"q":"*Be careful*! You almost stepped on that snake.","o":["Keep on!","Pick up!","Point out!","Look out!"],"a":3,"e":"*Look out* = watch out = be careful = pay attention = be careful"},{"q":"The tour guide *called our attention to* a lot of old buildings.","o":["got through","stood up","turned up","pointed out"],"a":3,"e":"*Point out* = call attention to = tell people about = show = demonstrate"},{"q":"I have too much work already. I can't *accept the responsibility for* any more.","o":["take on","look in on","see about","keep on"],"a":0,"e":"*Take on* = to accept the responsibility for more work or for more duties"},{"q":"Some prisoners have to *subsist on* nothing but bread and water for months.","o":["deal with","keep on","look out for","live on"],"a":3,"e":"*Live on* = to survive on. You live on food. You live on a certain amount of money per month."},{"q":"We Can't *remain at an equal pace with* that car. It's too fast.","o":["drop out of","check up on","get on with","keep up with"],"a":3,"e":"*Keep up with* = maintain the same speed as someone or something else."},{"q":"Some people say President Grant was *crooked*.","o":["honest","beneficent","short","dishonest"],"a":3,"e":"*Crooked* = not straight = slang for dishonest"},{"q":"Report to the Major _____ once!","o":["at","on","in","to"],"a":0,"e":"fixed expression *at* once, meaning without delay, without hesitation"},{"q":"Do you believe _____ ghosts?","o":["at","in","of","to"],"a":1,"e":"fixed expression You *believe in* something."},{"q":"Musicians have to spend most of their time _____ the road.","o":["on","in","of","for"],"a":0,"e":"fixed expression Traveling *on* the road by bus or car or van."},{"q":"My country has been involved _____ wars for most of this century.","o":["in","to","at","of"],"a":0,"e":"fixed expression You are *involved in* something."},{"q":"I am very good _____ tennis.","o":["of","at","to","for"],"a":1,"e":"fixed expression You are *good at* something or *bad at* something."},{"q":"My neighbor was convicted _____ car theft.","o":["of","by","with","to"],"a":0,"e":"Fixed expression to be *convicted of* First, he was *charged with* the crime."},{"q":"I am ashamed _____ myself.","o":["of","to","by","for"],"a":0,"e":"fixed expression. Ashamed of. Opposite is proud of."},{"q":"I give up! You are _____ redemption!","o":["around","across","beyond","over"],"a":2,"e":"*Beyond* means past the point of. Fixed expressions: beyond hope, beyond redemption, beyond salvation."},{"q":"If I tell you a secret, will you promise to keep it _____ strictest confidence?","o":["at","of","in","to"],"a":2,"e":"fixed expression to keep *in* confidence"},{"q":"It's time to *hit the hay*.","o":["eat something","start fighting","save money","go to bed"],"a":3,"e":"*Hit the hay* = go to bed. In the old days, people slept on piles of hay."},{"q":"I told you a little white lie.","o":["I fibbed.","I flinched.","I forged.","I framed."],"a":0,"e":"A *little white lie* = a small lie that is not serious = a *fib*."},{"q":"_____ fire, do not try to use the elevators.","o":["In accordance with","In care of","In case of","By means of"],"a":2,"e":"fixed expression meaning \"if it should happen.\" *In case of* rain, the game will be postponed. In case of an emergency, call 911."},{"q":"That picture is going to cost you *two grand*.","o":["$2","$200","$2000","$2,000,000"],"a":2,"e":"a grand = slang term for a thousand dollars *five grand* = $5,000"},{"q":"The new mechanic was warned that anyone who doesn't *pull their weight* will be moved to the night shift.","o":["do a fair share of the work","lift heavy parts without help","arrive at work on time","follow every safety rule"],"a":0,"e":"Pull your weight = do your fair share of the work in a team."},{"q":"Having worked at a supply depot before, the new logistics officer was able to *start working effectively from her very first day*.","o":["hit the ground running","bite off more than she could chew","get cold feet","drag her feet"],"a":0,"e":"Hit the ground running = start a new job or activity quickly and successfully, with no slow start."},{"q":"He's only been in the unit for a week, so *cut him some slack* if he gets lost on base.","o":["don't be too hard on him","show him a shorter route","report him to his sergeant","lend him your map"],"a":0,"e":"Cut someone some slack = be less strict or critical with someone because of their situation."},{"q":"Because of budget cuts, the plan to renovate the base gym has been put *on the back burner*.","o":["postponed for now","canceled for good","made a top priority","handed to the dining facility"],"a":0,"e":"On the back burner = postponed or given low priority: not canceled, but nobody is working on it now."},{"q":"After the company lost its biggest contract, several engineers decided to *leave and go to work for a competitor*.","o":["jump ship","hold the fort","toe the line","stay the course"],"a":0,"e":"Jump ship = suddenly leave an organization or team, often to join another one."},{"q":"Sorry I didn't answer your email — I've been *snowed under* since the audit started.","o":["extremely busy with work","stuck at home by bad weather","feeling sick and tired","away from the office on leave"],"a":0,"e":"Snowed under = having so much work that you can hardly deal with it."},{"q":"A weekend in San Antonio won't *break the bank* if we stay at the base lodging.","o":["cost too much money","take too much time","be too crowded","need special permission"],"a":0,"e":"Not break the bank = not cost too much; be affordable."},{"q":"We've been *pinching pennies* all year so we can afford a trip to see my parents in Ohio.","o":["spending as little as possible","working extra shifts on weekends","borrowing money from friends","applying for a bank loan"],"a":0,"e":"Pinch pennies = be very careful with money and spend as little as possible."},{"q":"In many military families today, both spouses *earn the money that pays the household bills*.","o":["bring home the bacon","rule the roost","keep up with the Joneses","talk shop"],"a":0,"e":"Bring home the bacon = earn the money that supports a family. (Rule the roost = be the boss at home; keep up with the Joneses = try to own as much as the neighbors.)"},{"q":"I'd love to join you on the ski trip, but I'm *short of money* until payday.","o":["strapped for cash","rolling in dough","made of money","sitting on a gold mine"],"a":0,"e":"Strapped for cash = having very little money at the moment. (Rolling in dough / made of money = very rich.)"},{"q":"Three restaurants near the main gate *went out of business* during the pandemic.","o":["went belly up","went the extra mile","went Dutch","went with the flow"],"a":0,"e":"Go belly up = fail completely; go bankrupt (like a dead fish floating upside down)."},{"q":"The deal to keep the factory open was signed *at the last possible moment*, only hours before the deadline.","o":["at the eleventh hour","around the clock","at the drop of a hat","once in a blue moon"],"a":0,"e":"At the eleventh hour = at the last possible moment before a deadline."},{"q":"Our flight was delayed four hours, so we *killed time* by walking around the airport shops.","o":["passed the time while waiting","spent too much money","complained to the airline staff","rushed to find another flight"],"a":0,"e":"Kill time = do something to make the time pass while you wait."},{"q":"Sergeant Lee is the kind of person who will volunteer *instantly and without any hesitation*.","o":["at the drop of a hat","once in a blue moon","by the skin of his teeth","behind closed doors"],"a":0,"e":"At the drop of a hat = immediately, without hesitating or needing to be asked twice."},{"q":"The rear guard's mission was to slow the enemy down and *gain extra time* for the main column to withdraw.","o":["buy time","kill time","make time","do time"],"a":0,"e":"Buy time = delay something so that you have more time. (Kill time = pass time while waiting; make time = find time for something; do time = serve a prison sentence.)"},{"q":"Getting a slot at Ranger School this year is *a long shot*, but Private Hale plans to apply anyway.","o":["a slim chance","a shooting test","a distant post","a sure thing"],"a":0,"e":"A long shot = something that has only a small chance of succeeding."},{"q":"When you can't decide between two good job offers, sometimes you just have to *go with your gut*.","o":["trust your instincts","ask for more money","eat before deciding","follow your boss's advice"],"a":0,"e":"Go with your gut = follow your instinct or feeling instead of long analysis."},{"q":"Free college tuition in exchange for two more years of service? For me, that was *a no-brainer*.","o":["an easy decision","a foolish mistake","a difficult choice","a crazy idea"],"a":0,"e":"A no-brainer = a decision so easy and obvious that you hardly need to think about it."},{"q":"Captain Wells had planned to retire, but she *had a change of heart* and signed up for another tour.","o":["changed her mind","had heart surgery","felt very sad","lost her courage"],"a":0,"e":"Have a change of heart = change your opinion or decision about something."},{"q":"The weather forecast was uncertain, but the commander decided to *be extra careful* and cancel the night jump.","o":["err on the side of caution","throw caution to the wind","push his luck","play devil's advocate"],"a":0,"e":"Err on the side of caution = choose the safer option when you are not sure. (Throw caution to the wind = take a big risk.)"}]},{"id":"i_pv","sec":"Idioms","title":"Phrasal verbs","desc":"Make up, pick up, put aside...","items":[{"q":"My date *stood me up* last night.","o":["took me dancing","didn't even show up","brought me flowers and candy","showed me a great time"],"a":1,"e":"stand sb up: to intentionally fail to meet someone when you said you would, especially I don't know if I've been stood up or if she's just late - I'll wait another half hour."},{"q":"That song really *recalls* good memories of when I lived with my grandmother.","o":["brings back","cheers up","thinks over","turns over"],"a":0,"e":"*Bring back* = to make you remember something from the past. It brings a memory back to your brain."},{"q":"My father doesn't *have a favorable opinion of* people who smoke cigars.","o":["approve of","part with","be in on","catch up with"],"a":0,"e":"*Approve of* = have a favorable opinion of = think something is OK"},{"q":"You should *review* this vocabulary list before we take the test.","o":["do over","go over","be over","send over"],"a":1,"e":"go over = review = look at again = study"},{"q":"*I dropped off* during the history lecture.","o":["fell out of a chair","died","let something fall","fell asleep"],"a":3,"e":"*Drop off* = to fall asleep (while sitting up in a chair)"},{"q":"*Carefully consider all the details* before you do it.","o":["Get it across","Think it through","Come over it","Take it back"],"a":1,"e":"phrasal verb think through = carefully consider everything in advance"},{"q":"In Japan, many people *remove* their shoes when they enter a house.","o":["hang up","take off","put away","drop off"],"a":1,"e":"*Take off* = remove an item of clothing. Take off your hat when you enter a building."},{"q":"The supervisors will not *tolerate* cheating on the tests.","o":["think through","turn over","put up with","look up to"],"a":2,"e":"*Put up with* = tolerate = let something happen"},{"q":"It's hot now. I think I'll *store* all my sweaters for the summer.","o":["put away","take out","drop out","keep on"],"a":0,"e":"*Put away* = put something in storage, put something in a different place for later use."},{"q":"Before you buy that coat, you should *determine it if fits well*.","o":["try it out","do it over","try it on","check it off"],"a":2,"e":"*Try on* = to put clothing on to check the fit"},{"q":"We *expected him to come* for an hour before we finally left without him.","o":["waited for him","dropped him off","thought him up","made him over"],"a":0,"e":"*Wait for* = not leave until someone arrives = expect someone to arrive"},{"q":"When you get things at the store, *mark those items on the list*.","o":["check them off","check them out","check them in","check up on them"],"a":0,"e":"*Check something off* = to mark items on a list to show that you have taken care of them."},{"q":"We must *begin to consider* prepositions next week.","o":["talk back to","turn over","get on","take up"],"a":3,"e":"*Take up* = begin to consider = start doing something He's going to take up tennis next summer."},{"q":"The fire alarm bell *rang* at 9:25.","o":["went off","turned off","ran into","stood by"],"a":0,"e":"*Go off* = to explode = to activate = to ring Things that can go off are bombs, grenades, alarms signals, bells, alarm clocks, timers"},{"q":"I was *brought up* by my grandparents in a small town.","o":["reared","steered","leered","cheered"],"a":0,"e":"to bring up = to raise = to rear = to bring up = to help grow up"},{"q":"Poor weather _____ the helicopter from taking off.","o":["determined","subjected","prevented","avoided"],"a":2,"e":"*Prevented from taking off* means stopped it from doing so."},{"q":"The reporters were crowding around the injured athlete, so security asked them to ______ and give her some space.","o":["back off","cut off","log off","pay off"],"a":0,"e":"back off = move away; stop pressuring someone."},{"q":"Early reports said the fire started in the kitchen, and the investigators' findings later ______ that theory.","o":["bore out","bore down","gave off","wore off"],"a":0,"e":"bear out = support or confirm a story or theory."},{"q":"Jenna ______ her frustration for months until she finally exploded at a staff meeting.","o":["bottled up","backed up","made up","took up"],"a":0,"e":"bottle up = hide strong feelings for a long time."},{"q":"After failing his first inspection, Private Kim ______ and made sure his gear was perfect every morning.","o":["buckled down","buckled up","broke down","showed up"],"a":0,"e":"buckle down = begin to work seriously; buckle up = fasten your seat belt."},{"q":"The roof of the old warehouse *caved in* under the weight of the heavy snow.","o":["collapsed","leaked","was repaired","shook"],"a":0,"e":"cave in = fall down or inward; collapse."},{"q":"The plan for a new firing range *came up against* strong opposition from local residents.","o":["met","avoided","created","ignored"],"a":0,"e":"come up against = have to deal with a problem or opposition."},{"q":"The doctor told him to *cut back on* coffee and get more sleep.","o":["drink less","drink more","stop buying","switch to"],"a":0,"e":"cut back on = reduce the amount of something."},{"q":"The infantry company was ordered to ______ on the ridge and hold it until reinforcements arrived.","o":["dig in","dig up","pull out","give in"],"a":0,"e":"dig in = prepare a defensive position and stay there."},{"q":"Before the move, we *made* a list of everything that needed to be packed.","o":["drew up","drew on","drew back","drew in"],"a":0,"e":"draw up a list = write a list (draw on = use your experience or resources)."},{"q":"Rising fuel prices are *eating into* the trucking company's profits.","o":["reducing","increasing","protecting","measuring"],"a":0,"e":"eat into = use up or reduce part of something, such as money or time."},{"q":"Use a rake to ______ the gravel before you lay the paving stones.","o":["even out","knock out","give out","cut out"],"a":0,"e":"even out = make a surface flat and level."},{"q":"Interest in the book club *fizzled out* after a few months.","o":["slowly disappeared","grew very quickly","was renewed","became more official"],"a":0,"e":"fizzle out = gradually end in a weak or disappointing way."},{"q":"Most units ______ soldiers who show up late to formation, even by a minute.","o":["frown on","look up to","stand by","go along with"],"a":0,"e":"frown on = think that something or someone's behavior is wrong."},{"q":"The thief *handed over* the stolen wallet as soon as the officers arrived.","o":["surrendered","hid","dropped","emptied"],"a":0,"e":"hand over = give something to someone, often because you are told to."},{"q":"The two departments met on Monday to *iron out* their differences over the new schedule.","o":["settle","discover","increase","report"],"a":0,"e":"iron out = solve small problems or differences."},{"q":"After the loss, the coach *strongly criticized* the referees in front of reporters.","o":["lashed out at","caught up with","looked up to","made up for"],"a":0,"e":"lash out at = criticize someone angrily."},{"q":"The aircraft climbed to 30,000 feet and then *began to fly horizontally*.","o":["leveled off","leveled up","took off","touched down"],"a":0,"e":"level off = (of an aircraft) stop climbing and fly level."},{"q":"Remember to *log on* with your new password before the online safety course closes at 1600.","o":["enter the system","shut down the computer","print your certificate","change your settings"],"a":0,"e":"log on = connect to a computer system or website, usually with a username and password."},{"q":"Specialist Grant was on guard duty during the unit party, so he ______ the barbecue and the awards.","o":["missed out on","made up for","ran out of","looked out for"],"a":0,"e":"miss out on = not get to enjoy something good because you are absent or too late."},{"q":"The gate guard *wrote down* the license plate of every car that came onto the post after midnight.","o":["noted down","brought down","turned down","knocked down"],"a":0,"e":"note down = write down. turn down = refuse; knock down = hit to the ground or destroy."},{"q":"We're not sure yet how the new shift schedule will ______, but the first week looked promising.","o":["pan out","pass out","put out","pull out"],"a":0,"e":"pan out = develop or turn out. pass out = faint; put out = extinguish; pull out = withdraw."},{"q":"The risky decision *proved successful*: the small company's app now has over a million users.","o":["paid off","paid back","fell through","broke down"],"a":0,"e":"pay off = succeed. fall through = fail to happen; break down = stop working."},{"q":"Technicians spent all morning trying to *pin down* the cause of the radar failure.","o":["identify exactly","repair quickly","hide from the boss","explain to others"],"a":0,"e":"pin down = find out or identify something exactly."},{"q":"Bad weather has *pushed back* the parachute jump to Thursday afternoon.","o":["delayed","canceled","moved earlier","shortened"],"a":0,"e":"push back = postpone, move to a later time."},{"q":"After a twenty-minute fight, my father finally ______ a huge catfish at Lake Texoma.","o":["reeled in","reeled off","rolled in","let off"],"a":0,"e":"reel in = pull a fish toward you by winding the line. reel off = say a list quickly."},{"q":"With her strong math background, Jana ______ the navigation course while others struggled.","o":["sailed through","sailed off","fell behind","went off"],"a":0,"e":"sail through = do something successfully and easily."},{"q":"After a suspicious package was found, MPs ______ the parking lot and called the bomb squad.","o":["sealed off","sealed in","set off","showed off"],"a":0,"e":"seal off = close an area. set off = cause to explode."},{"q":"The driver took several side streets to *escape from* the car that was following him.","o":["shake off","shake up","show off","take off"],"a":0,"e":"shake off = escape from someone following you. shake up = upset or reorganize."},{"q":"The new platoon leader took a few days to *size up* her soldiers before making any changes.","o":["judge","measure for uniforms","promote","replace"],"a":0,"e":"size up = observe and form an opinion of."},{"q":"Stress at work sometimes *spills over* into family life.","o":["spreads into","disappears from","is replaced by","is caused by"],"a":0,"e":"spill over = spread from one area into another."},{"q":"Drink plenty of water and rest in the shade to ______ heat exhaustion during the march.","o":["stave off","stand off","set off","start off"],"a":0,"e":"stave off = prevent. set off = cause something to start."},{"q":"The colonel *swore in* twenty new recruits in front of their proud families.","o":["gave the oath to","shouted angrily at","trained","welcomed home"],"a":0,"e":"swear in = officially admit someone by having them take an oath."},{"q":"If you *trade in* your old phone, the store will give you $200 off a new one.","o":["give it as part payment","repair it","sell it online","throw it away"],"a":0,"e":"trade in = give an old item to lower the price of a new one."},{"q":"The factory will *gradually reduce* production over the next year before it closes for good.","o":["wind down","write down","break down","back down"],"a":0,"e":"wind down = reduce gradually before ending. break down = stop working."}]},{"id":"l_mix","sec":"Listening","title":"Listening","desc":"Recorded American voices, 5 question types","items":[{"id":"L01","k":"s","L":[["M","The flight to San Antonio leaves at fourteen fifteen, not at four fifteen.","L01-1.mp3?v=2ab4893d10"]],"q":"When does the flight leave?","o":["At 2:15 in the afternoon","At 4:15 in the afternoon","At 4:50 in the morning","At 2:50 in the afternoon"],"a":0,"e":"In military time, fourteen fifteen (1415) is 2:15 p.m. The speaker corrects the mistake \"four fifteen\"."},{"id":"L1849","k":"s","L":[["M","The flight attendants won't serve meals until the plane reaches cruising altitude.","L1849-1.mp3?v=6255198587"]],"q":"When will meals be served?","o":["After the plane reaches cruising altitude","Before takeoff","During takeoff","After landing"],"a":0,"e":"\"Won't ... until\" means only after that point."},{"id":"L2067","k":"s","L":[["M","My family is coming to visit for the holidays, so I took two weeks off.","L2067-1.mp3?v=c2f41a5069"]],"q":"Why did he take time off?","o":["His family is visiting.","He is sick.","He is moving.","He is going on a trip."],"a":0,"e":"He wants time with his family."},{"id":"L2326","k":"s","L":[["W","The bridge is safe for cars but not for heavy trucks.","L2326-1.mp3?v=8c0e5b8e34"]],"q":"What can be concluded about the bridge?","o":["Big trucks should cross somewhere else.","Cars should avoid the bridge.","The bridge is safe for every vehicle.","Small cars are not allowed on the bridge."],"a":0,"e":"The bridge is unsafe for heavy trucks, so they must use a different way."},{"id":"L2654","k":"s","L":[["M","I filled up the tank before returning the car, but they still charged me because the gauge wasn't quite on full.","L2654-1.mp3?v=d1f40393b2"]],"q":"Why was the man charged?","o":["The car needed a bit more gas.","He returned the car late.","He forgot to fill up the tank.","The fuel gauge was broken."],"a":0,"e":"The gauge was not completely on full, so the company charged him for the missing fuel."},{"id":"L2848","k":"s","L":[["M","Always save your work every few minutes, because this old computer sometimes freezes without any warning.","L2848-1.mp3?v=985e325662"]],"q":"Why does the man give this advice?","o":["The computer could stop working suddenly.","The computer has very little storage space.","Files are deleted every few minutes.","The computer gives a warning before it shuts down."],"a":0,"e":"The computer can freeze with no warning, so unsaved work could be lost."},{"id":"L3041","k":"s","L":[["W","The new fuel cans hold five gallons, a gallon more than the old ones, and we're issuing two per vehicle.","L3041-1.mp3?v=008ce748f4"]],"q":"How much fuel can each vehicle carry in the new cans?","o":["Ten gallons.","Eight gallons.","Twelve gallons.","Six gallons."],"a":0,"e":"Two cans of five gallons each make ten gallons per vehicle."},{"id":"L6626","k":"s","L":[["W","As the river kept rising, the colonel warned that this situation needed prompt action, not more meetings.","L6626-1.mp3?v=e5d5c026ab"]],"q":"What did the colonel want?","o":["A fast response","A longer discussion","A different commander","More time to rest"],"a":0,"e":"Prompt action means quick action, so he wanted a fast response instead of meetings."},{"id":"L6119","k":"s","L":[["M","On the training map, every green triangle represents a supply depot, and each blue circle represents a medical tent.","L6119-1.mp3?v=d022deba44"]],"q":"What does a blue circle show?","o":["A place for first aid","A storage area for supplies","A parking area for trucks","A post for the commanders"],"a":0,"e":"A blue circle represents a medical tent, which is a first-aid place."},{"id":"L6848","k":"s","L":[["M","In front of the class, Staff Sergeant Lowe remarked that my handwriting looked like a child's, and I felt my face turn red.","L6848-1.mp3?v=da5e0726cb"]],"q":"Why did the speaker feel embarrassed?","o":["The sergeant's comment hurt his pride.","The whole class was laughing at a joke.","He realized he had forgotten his notebook.","He arrived late and missed the first part."],"a":0,"e":"A remark is a comment; the sergeant's words about his handwriting embarrassed him."},{"id":"L03","k":"r","L":[["M","How long have you been stationed at this base?","L03-1.mp3?v=f27ddd406c"]],"q":"Choose the best answer.","o":["Since last March.","At the main gate.","By bus, every morning.","About ten miles from here."],"a":0,"e":"\"How long\" asks about a period of time. \"Since last March\" gives the start of that period."},{"id":"L1238","k":"r","L":[["W","Do you want me to drive you to the airport?","L1238-1.mp3?v=edb838a3f6"]],"q":"Choose the best answer.","o":["That would be great, thanks.","The airport is far.","I drove there yesterday.","My flight is long."],"a":0,"e":"It is an offer; the reply accepts."},{"id":"L1369","k":"r","L":[["M","If I don't pass the CPR certification on the first try, can I retake it?","L1369-1.mp3?v=1e493cec05"]],"q":"Choose the best answer.","o":["Yes, but you'll have to wait a week.","I passed mine on the first try.","It came by certified mail.","I'll try to take it with me."],"a":0,"e":"He can take the test again, but only after waiting a week."},{"id":"L1499","k":"r","L":[["W","Should I bring an umbrella, or is the rain supposed to stop soon?","L1499-1.mp3?v=ac756272ab"]],"q":"Choose the best answer.","o":["I'd take one just to be safe.","The bus stop is right around the corner.","I brought it back yesterday.","I'm supposed to be there soon."],"a":0,"e":"The speaker advises bringing an umbrella in case it keeps raining."},{"id":"L1631","k":"r","L":[["W","How's your father getting along since his knee surgery last month?","L1631-1.mp3?v=3007f5b94e"]],"q":"Choose the best answer.","o":["He's back on his feet, thank goodness.","He got along well with everyone in his unit.","The surgery took about four hours.","Next month, I think."],"a":0,"e":"\"Back on his feet\" means he has recovered and can move around normally again."},{"id":"L3140","k":"r","L":[["M","Would you mind signing for the GPS units while I load the water cans?","L3140-1.mp3?v=00a7000db7"]],"q":"Choose the best answer.","o":["Sure. Who do I give the paperwork to?","I already signed up for that course last week.","About twenty cans, I think.","The truck is low on water."],"a":0,"e":"She agrees and asks a practical question about the paperwork."},{"id":"L3243","k":"r","L":[["W","The clinic called to move my physical to Tuesday, but I've got a range day then.","L3243-1.mp3?v=81217b709a"]],"q":"Choose the best answer.","o":["Then you'd better ask for a different day.","I moved here on a Tuesday.","The range is a long way from the clinic.","Physical training starts at six every morning."],"a":0,"e":"He advises her to ask the clinic for another date."},{"id":"L3347","k":"r","L":[["W","Doesn't the speed limit drop to forty-five once you get into town?","L3347-1.mp3?v=b0965b3bf5"]],"q":"Choose the best answer.","o":["Yes, so you'd better slow down now.","I dropped my keys in town.","There's no limit to the number of bags.","I was forty-five on my last birthday."],"a":0,"e":"He confirms the lower limit and tells her to reduce her speed."},{"id":"L3451","k":"r","L":[["W","The PX closes at six on Sundays, doesn't it? I still need a birthday card.","L3451-1.mp3?v=76f437fd90"]],"q":"Choose the best answer.","o":["They changed it to eight, I think.","It's pretty close to the gym.","I closed my bank account on Sunday.","Happy birthday! How old are you?"],"a":0,"e":"He tells her the store now stays open later, so she still has time."},{"id":"L4633","k":"r","L":[["W","Would you mind showing me how to check the tire pressure before I take the van out?","L4633-1.mp3?v=b72a127b22"]],"q":"Choose the best answer.","o":["Sure, let me grab the gauge from my truck.","I've been under a lot of pressure lately.","They checked it out of the motor pool already.","I'm too tired to go out tonight, thanks."],"a":0,"e":"He agrees to help and goes to get the tool used to measure tire pressure."},{"id":"L04","k":"d","L":[["W","Are you coming to the briefing at zero eight hundred?","L04-1.mp3?v=ccc6d507f8"],["M","I wouldn't miss it for the world.","L04-2.mp3?v=c18f292fb1"]],"q":"What does the man mean?","o":["He will certainly go to the briefing.","He does not want to go to the briefing.","He has never been to a briefing.","He thinks the briefing is too early."],"a":0,"e":"\"I wouldn't miss it for the world\" means \"I will certainly be there.\""},{"id":"L540","k":"d","L":[["W","I'm going to the store. Do you need anything?","L540-1.mp3?v=3c3b6ec297"],["M","Could you get me some batteries?","L540-2.mp3?v=13d7639e78"]],"q":"What does the man want the woman to do?","o":["Buy something for him while she is out","Check whether his batteries are still good","Take him along with her to the store","Charge his batteries before she goes out"],"a":0,"e":"He asks her to get him batteries at the store, so she will be shopping for him."},{"id":"L764","k":"d","L":[["M","Why is your car making that noise?","L764-1.mp3?v=4d86cd95fd"],["W","The muffler has a hole in it.","L764-2.mp3?v=72ededf33a"]],"q":"What causes the noise?","o":["A hole in the muffler","A flat tire","A loose door","The radio"],"a":0,"e":"The damaged muffler makes noise."},{"id":"L2400","k":"d","L":[["W","Has the landlord done anything about the noise from upstairs?","L2400-1.mp3?v=f81c51ff34"],["M","He's talked to the neighbors twice, but they still play music past midnight.","L2400-2.mp3?v=cf0f88f294"]],"q":"What can be concluded?","o":["The problem has not been solved.","The landlord himself plays loud music.","The neighbors have moved out.","The man works past midnight."],"a":0,"e":"Despite two talks, the neighbors are still noisy, so nothing has changed."},{"id":"L3617","k":"d","L":[["W","My orders for the conference in Denver don't authorize a rental car. How am I supposed to get around?","L3617-1.mp3?v=ba663d1eea"],["M","The hotel runs a free shuttle to the training center, and you can claim taxis for anything official.","L3617-2.mp3?v=faa1cd8b5a"]],"q":"What does the man tell the woman?","o":["Other options will cover her travel.","She should ask to change her orders.","She can rent a car with her own money.","The conference was moved to the hotel."],"a":0,"e":"A hotel shuttle and reimbursed taxis will let her get around without a rental car."},{"id":"L3746","k":"d","L":[["M","I've been waiting on the video call for ten minutes, and nobody else has joined.","L3746-1.mp3?v=f29add1ca5"],["W","The invite was in Eastern time. It doesn't start for another hour here.","L3746-2.mp3?v=3313c7f162"]],"q":"Why hasn't anyone joined the call?","o":["The man mistook the starting time.","The call was canceled an hour ago.","The video link is not working.","Everyone else joined ten minutes early."],"a":0,"e":"The time on the invitation was in another time zone, so the call starts an hour later."},{"id":"L3875","k":"d","L":[["W","My orders to Korea came through. Do I need any shots before I go?","L3875-1.mp3?v=b320af4382"],["M","Probably a few. Take your shot record to immunizations; they'll compare it with the requirements for that region.","L3875-2.mp3?v=0fc018e2c1"]],"q":"What should the woman do first?","o":["Have her vaccine records checked","Get every shot before receiving orders","Ask her unit about travel to Korea","Request a copy of her new orders"],"a":0,"e":"The immunization clinic will compare her record with what is required for Korea."},{"id":"L4005","k":"d","L":[["W","I can't decide between the cheaper vacuum and the one that's twice the price.","L4005-1.mp3?v=0111a3778a"],["M","My dad always says, 'Buy cheap, buy twice.' Ours broke after six months.","L4005-2.mp3?v=159e294201"]],"q":"What does the man suggest?","o":["The better model may save money in the end.","She should buy two of the cheaper vacuums.","His father can lend her his vacuum.","Prices will drop in six months."],"a":0,"e":"A cheap product may break and need replacing, so the better one can cost less over time."},{"id":"L4774","k":"d","L":[["M","The seller says the car has only forty thousand miles and has never been in an accident.","L4774-1.mp3?v=c383c168d2"],["W","That may be true, but I wouldn't hand over a penny until a mechanic has looked at it.","L4774-2.mp3?v=fba63adbeb"]],"q":"What is the woman's advice?","o":["Have the car inspected before paying","Buy the car since the mileage is low","Ask the seller about the accident","Pay the seller a small deposit first"],"a":0,"e":"She says not to pay anything until a mechanic checks the car."},{"id":"L6266","k":"d","L":[["M","Should we invite Lieutenant Carr to the barbecue?","L6266-1.mp3?v=abba14a484"],["W","If you want everyone to go quiet. He's such a wet blanket.","L6266-2.mp3?v=6c4848ae25"]],"q":"What does the woman think of Lieutenant Carr?","o":["He spoils the fun","He cooks very well","He talks too much","He is always late"],"a":0,"e":"A wet blanket is a person who spoils other people's fun."},{"id":"L62","k":"c","L":[["W","My flight gets in at nine forty tonight. Could you pick me up at the airport?","L62-1.mp3?v=8f38737809"],["M","Sure, but I'm on duty until ten. Is ten thirty all right? I'll meet you outside baggage claim.","L62-2.mp3?v=d57d8761c5"],["W","That's fine. It always takes a while to get my bags anyway.","L62-3.mp3?v=bb53b339fe"]],"q":"At what time will the man pick the woman up?","o":["At 10:30 p.m.","At 9:40 p.m.","At 10:00 p.m.","At 10:40 p.m."],"a":0,"e":"The man is \"on duty until ten\", so he offers \"ten thirty\", and the woman says \"That's fine.\" Nine forty is when her flight lands."},{"id":"L190","k":"c","L":[["M","I'd like to see Dr. Lewis this week.","L190-1.mp3?v=2c6b83cfb6"],["W","Her first opening is next Thursday, but Dr. Ford can see you tomorrow at three.","L190-2.mp3?v=db20e64fe9"],["M","Dr. Ford is fine.","L190-3.mp3?v=0cb9ec4d62"]],"q":"Why does the woman mention Dr. Ford?","o":["Dr. Lewis is not available soon enough.","Dr. Ford is the man's regular doctor.","Dr. Lewis has stopped working at the clinic.","Dr. Ford has an opening next Thursday."],"a":0,"e":"Dr. Lewis can't see him until next Thursday, and he wants an appointment this week, so she offers Dr. Ford tomorrow."},{"id":"L275","k":"c","L":[["W","Doctor, I'm always tired. I sleep only five hours a night.","L275-1.mp3?v=a4fe1243bf"],["M","You need at least seven. Let's look at your schedule.","L275-2.mp3?v=c838df5f8a"],["W","All right, Doctor.","L275-3.mp3?v=560e928307"]],"q":"What does the doctor say the woman needs?","o":["More sleep","More exercise","A new job","Vitamins"],"a":0,"e":"She sleeps only five hours a night, and he says she needs at least seven."},{"id":"L364","k":"c","L":[["W","Is there a gas station nearby? My fuel light just came on.","L364-1.mp3?v=783b922ff9"],["M","There's one about two miles ahead. If the light only just came on, you'll be fine.","L364-2.mp3?v=af1ebbede1"],["W","I hope so.","L364-3.mp3?v=9868efc62b"]],"q":"Why does the man think she'll be fine?","o":["She still has a little fuel left","She filled up the tank this morning","The station is right around the corner","Her car uses very little gas"],"a":0,"e":"The light has only just come on, which still leaves a few miles of fuel, and the station is two miles away."},{"id":"L4160","k":"c","L":[["M","This GPS says we're in the middle of the lake. The sticker says it was last updated in March of last year.","L4160-1.mp3?v=38fbb2c675"],["W","That's the problem. They should be updated every six months. Use the map and compass for now.","L4160-2.mp3?v=8d92b6b704"],["M","Okay. We'll update it when we're back.","L4160-3.mp3?v=5903fd2441"]],"q":"Why is the GPS giving the wrong position?","o":["Its software is out of date","It was dropped in the lake","Its battery is running low","The man is reading it incorrectly"],"a":0,"e":"The sticker shows it was last updated in March of last year, but it should be updated every six months."},{"id":"L4205","k":"c","L":[["W","They want one of us at the exercise planning conference in Georgia in May, but my son graduates from high school that week.","L4205-1.mp3?v=38a9f85743"],["M","Then I'll go. Send me the registration link, and I'll start my travel request.","L4205-2.mp3?v=b7d8660895"],["W","Thanks. I'll email it today.","L4205-3.mp3?v=335d2eeda3"]],"q":"Why won't the woman attend the conference?","o":["Her child has an important ceremony","The registration is already closed","She has to plan next year's exercise","She doesn't want to travel to Georgia"],"a":0,"e":"Her son's high school graduation is the same week."},{"id":"L4249","k":"c","L":[["W","My flight from Denver landed late, and I missed my connection to Boston. Is there anything tonight?","L4249-1.mp3?v=4e11ff78b9"],["M","The eight o'clock is full, so the next seat is at seven ten tomorrow morning. Since the delay was our fault, here's a hotel voucher.","L4249-2.mp3?v=165aa67bba"],["W","Tomorrow morning? Well, at least I'll get some sleep.","L4249-3.mp3?v=513187f622"]],"q":"Why will the airline pay for the woman's hotel?","o":["The airline was to blame for the delay","The eight o'clock flight was canceled","She belongs to its frequent flyer program","She got to the airport too late to board"],"a":0,"e":"The agent says the delay was the airline's fault, so it gives her a hotel voucher."},{"id":"L4293","k":"c","L":[["W","I found an almost new leather couch online for two hundred dollars, but it won't fit in my car.","L4293-1.mp3?v=c2b7ad4082"],["M","My brother has a pickup truck. If he's free Saturday, we could go get it together.","L4293-2.mp3?v=8336a91b10"],["W","Perfect. The seller wants it picked up by Sunday anyway. I'll pay for his gas.","L4293-3.mp3?v=65931dc77e"]],"q":"What is the woman's problem?","o":["She has no way to transport the furniture","The couch is more expensive than she thought","The seller lives too far to visit","She has to pick up the couch by Saturday"],"a":0,"e":"The couch won't fit in her car, so she can't bring it home herself."},{"id":"L5006","k":"c","L":[["M","The commander wants an award for Specialist Chen before she leaves at the end of the month. When does the write-up need to be done?","L5006-1.mp3?v=d480eaecda"],["W","The paperwork takes about three weeks to get signed. So yesterday would have been nice.","L5006-2.mp3?v=0aabcf7cf2"],["M","Understood, ma'am. I'll start tonight.","L5006-3.mp3?v=3ef6e32071"]],"q":"What does the woman mean when she says, 'Yesterday would have been nice'?","o":["The award is already behind schedule","The write-up was finished yesterday","Specialist Chen left the unit last week","The paperwork can wait until next month"],"a":0,"e":"Saying 'yesterday would have been nice' means there is barely enough time left, because the paperwork takes three weeks and Chen leaves at the end of the month."},{"id":"L5050","k":"c","L":[["M","I want to rent a kayak from outdoor recreation this weekend. Have you done it?","L5050-1.mp3?v=439e51c972"],["W","Yes. They won't give you a paddle until you take their safety class. Bring a towel, because you'll probably tip over in the practice.","L5050-2.mp3?v=e3e91cdb19"],["M","Good to know. I'll take the class this Saturday.","L5050-3.mp3?v=f7238ecf2d"]],"q":"What can be concluded about the safety class?","o":["Students will probably get wet in it","It is offered only during the summer","It costs more than the kayak rental","It must be taken on a weekday evening"],"a":0,"e":"She tells him to bring a towel because he will probably tip over during the practice."},{"id":"L59","k":"k","L":[["W","Attention, please. The eleven forty train to Washington will leave from Track Six today, not from Track Two. Because of work on the tracks, the train is running about fifteen minutes behind schedule. We apologize for the delay.","L59-1.mp3?v=839f1b9b27"]],"q":"Which track will the Washington train leave from?","o":["Track 6","Track 2","Track 11","Track 15"],"a":0,"e":"The train \"will leave from Track Six today, not from Track Two.\" Eleven forty is the time of the train, and fifteen minutes is the delay."},{"id":"L976","k":"k","L":[["W","Attention, shoppers. For the next hour, all frozen foods are twenty percent off. This offer is good only until three o'clock, so hurry to aisle twelve and take advantage of these savings.","L976-1.mp3?v=84417372fd"]],"q":"What time is it probably now?","o":["About two o'clock","Just after three","Around noon","Twelve o'clock"],"a":0,"e":"The sale lasts for the next hour and ends at three, so it is about two now."},{"id":"L1021","k":"k","L":[["M","Honeybees are important to farmers because they carry pollen from flower to flower. This helps plants produce fruit and seeds. Without bees, many of the foods we eat would become rare and expensive.","L1021-1.mp3?v=9cf6248486"]],"q":"Why are honeybees important to farmers?","o":["They help plants produce fruit.","They make honey for farmers to sell.","They kill harmful insects.","They improve the soil."],"a":0,"e":"Pollination helps plants produce fruit."},{"id":"L1061","k":"k","L":[["M","Benjamin Franklin was a writer, scientist, and diplomat. He is famous for his experiments with electricity, including flying a kite in a thunderstorm. He also helped write the Declaration of Independence.","L1061-1.mp3?v=7191de0260"]],"q":"What does the speaker say about the kite?","o":["It was part of a scientific test","It was a gift to a diplomat","It was used to send messages","It was flown on a sunny day"],"a":0,"e":"Franklin flew the kite in a thunderstorm as one of his experiments with electricity."},{"id":"L1128","k":"k","L":[["W","Hi, this is Helen from the bank. Your new debit card has been mailed and should arrive within five business days. Please activate it by calling the number on the sticker.","L1128-1.mp3?v=ba39aee950"]],"q":"What is the main reason for Helen's call?","o":["To say a card is on its way","To ask for a new mailing address","To explain why a card was blocked","To report five missing payments"],"a":0,"e":"Helen says the new debit card has been mailed and should arrive soon."},{"id":"L4358","k":"k","L":[["M","Today you'll go through the vehicle rollover trainer. The crew compartment will turn on its side and then upside down, so secure everything loose before we start, including water bottles and phones. Keep your seat belt fastened until the vehicle stops moving completely. When it stops, the vehicle commander will call out, and each person will answer with a status. Then brace yourself with one hand, release the belt with the other, and exit through the nearest door.","L4358-1.mp3?v=6552a64cbd"]],"q":"What must happen right after the vehicle stops moving?","o":["The crew members report on their condition","Everyone unfastens the belt and gets out","Each soldier collects the loose water bottles","The commander leaves through the nearest door"],"a":0,"e":"When the vehicle stops, the commander calls out and each person answers with a status before anyone gets out."},{"id":"L4390","k":"k","L":[["M","Before you leave for the four-day weekend, a few rules. Anyone traveling more than two hundred and fifty miles from post needs an approved leave form, not just a pass. Get at least seven hours of sleep before any long drive, and stop every two hours. If you've been drinking, call a friend, a taxi, or your squad leader, any time of day or night. Formation is Tuesday at zero six thirty, and everyone will be there on time.","L4390-1.mp3?v=6b3e87abb2"]],"q":"What is required of soldiers who plan to travel far from post?","o":["They need formal permission to take leave.","They must stop every two hundred miles.","They must call their squad leader daily.","They must sleep seven hours every day."],"a":0,"e":"Soldiers going more than two hundred and fifty miles away need an approved leave form, not a pass."},{"id":"L4423","k":"k","L":[["W","Hi, Daniel, this is Karen from Westside Auto calling about your car. We finished the brake job this morning, but while it was up on the lift, our mechanic noticed that your front tires are badly worn. We didn't replace them because we needed your approval first. The car is safe to drive for now, and you can pick it up anytime before six. If you'd like us to put on new tires, call me back by three so we can order them today.","L4423-1.mp3?v=42973e9232"]],"q":"Why did the shop not change the tires?","o":["The owner had not agreed to it yet.","The needed tires were not in stock yet.","The mechanic ran out of time this morning.","The tires were safe enough to keep."],"a":0,"e":"Karen says they did not replace the tires because they needed Daniel's approval first."},{"id":"L4456","k":"k","L":[["M","Good afternoon, visitors. In fifteen minutes, our keepers will feed the sea lions at the outdoor pool next to the Ocean Cafe. It's a great show, and you'll learn how the animals are trained. Seats fill up quickly, so we recommend arriving early. Please note that the first three rows may get wet. Also, the penguin house is closed this afternoon for cleaning, but it will reopen tomorrow morning at nine.","L4456-1.mp3?v=f5df01c243"]],"q":"What does the speaker warn visitors about?","o":["Front seats may be splashed with water.","The show will be canceled if it rains.","The sea lions can be dangerous to touch.","The cafe will close during the show."],"a":0,"e":"The speaker says that people in the first three rows may get wet."},{"id":"L4489","k":"k","L":[["W","This is your Tuesday weather update. It'll be another warm, breezy day with highs near eighty-five. Unfortunately for allergy sufferers, the pollen count is very high, mostly from oak and pine trees, and the wind is spreading it everywhere. If you have allergies, keep your windows closed and try to stay indoors in the early morning, when pollen levels peak. Some relief is on the way: steady rain on Thursday should clear much of it from the air.","L4489-1.mp3?v=a7dd0f6b46"]],"q":"According to the report, when are pollen levels highest?","o":["Soon after the sun comes up","In the middle of the afternoon","During the rain on Thursday","Late in the evening hours"],"a":0,"e":"The reporter says pollen levels peak in the early morning."}]},{"id":"t_mod","sec":"Test","title":"Module test","desc":"Mixed questions, like the real test","items":[{"q":"I ______ on a houseboat in Austria since 1988.","o":["have lived","am","live","am living"],"a":0,"e":"since + a starting point (since 1988): present perfect, have lived."},{"q":"My cat is a real hunter; she ______ anything that moves.","o":["chasing","is chase","chase","chases"],"a":3,"e":"Habit, third person singular, so chases."},{"q":"I ______ in the Egyptian Navy for six years.","o":["am","am been","have been","has been"],"a":2,"e":"for + a duration up to now takes the present perfect."},{"q":"My teacher ______ to the graduation ceremony tomorrow.","o":["going","goes","is going","is go"],"a":2,"e":"A fixed arrangement -> present progressive with future meaning."},{"q":"My grandkids ______ the Internet right now, so you can't use the phone.","o":["surfing","surf","surfs","are surfing"],"a":3,"e":"right now -> present progressive."},{"q":"Craig and his family ______ in Buenos Aires last year at this time.","o":["were","was","has been","have been"],"a":0,"e":"Plural subject in the past, so were."},{"q":"Your mother ______ from Valencia airport 2 hours ago.","o":["call","calls","has called","called"],"a":3,"e":"2 hours ago -> simple past."},{"q":"According to the drill instructor, the trainees ______ the barracks right now.","o":["are cleaning","cleans","is cleaning","was cleaning"],"a":0,"e":"Plural subject with right now."},{"q":"I ______ to the Cherry Tree Festival next year in Japan.","o":["went","am go","am going","have gone"],"a":2,"e":"A settled plan -> be going to."},{"q":"Craig and I ______ to Ireland and ______ the famous Book of Kells.","o":["go ... see","have gone ... saw","went ... have seen","went ... saw"],"a":3,"e":"Two completed past actions."},{"q":"There ______ a lot of sniper attacks here in the last three months.","o":["are","was","is","have been"],"a":3,"e":"in the last three months takes the present perfect, plural."},{"q":"Q: Does your father still live in Lisbon? A: No, he ______ in Norway.","o":["live","living","is live","lives"],"a":3,"e":"Third person singular (he): lives."},{"q":"A: Does your family own a house? B: Neither. My family ______ an apartment.","o":["rent","rents","renting","is rent"],"a":1,"e":"Family is a singular collective, so rents."},{"q":"Q: Does your brother have dimples? A: No, he ______ dimples.","o":["hasn't","hadn't","doesn't have","doesn't has"],"a":2,"e":"Negative of have as a full verb in the present."},{"q":"Surprisingly, the people of that country ______ any gum disease.","o":["doesn't have","don't have","hasn't","isn't having"],"a":1,"e":"People is plural, so don't have."},{"q":"Q: Has Petty Officer Vance removed the device? A: No, he ______ removed it yet.","o":["doesn't have","don't have","hasn't","haven't"],"a":2,"e":"Tag question on the present perfect, singular."},{"q":"Q: How much area has the river flooded? A: The river ______ flooded any area at all.","o":["doesn't have","don't have","hasn't","haven't"],"a":2,"e":"Present perfect negative, singular."},{"q":"Q: How many times did he have a score below 60? A: He ______ any scores below 60.","o":["didn't has","don't have","didn't have","haven't"],"a":2,"e":"The answer repeats the simple past of the question: didn't have."},{"q":"Q: Does he have to take it again? A: Yes, he ______ to take it again.","o":["have","has","doesn't have","hasn't"],"a":1,"e":"Tag question on have to, singular."},{"q":"When I arrived home from school, the postman ______ a small parcel.","o":["was deliver","delivers","delivering","had delivered"],"a":3,"e":"An action earlier than another past action."},{"q":"Everybody ______ going to the dentist.","o":["dislikes","disliking","are dislike","is dislike"],"a":0,"e":"Everybody takes a singular verb."},{"q":"I ______ to the airport tomorrow.","o":["going","went","will go","am go"],"a":2,"e":"Simple future: will + the simple form of the verb (will go)."},{"q":"I ______ a good movie last night.","o":["see","saw","seeing","seen"],"a":1,"e":"\"Last night\" requires *past tense*."},{"q":"I ______ in the military for 6 years.","o":["is","am","are","have been"],"a":3,"e":"for 6 years, up to now: present perfect."},{"q":"He ______ promoted in 2005.","o":["got","get","is got","gotten"],"a":0,"e":"Informal passive with get in the past."},{"q":"My dog ______ cars all the time.","o":["chases","is chase","chase","chasing"],"a":0,"e":"Habit, third person singular."},{"q":"Capt. Barrow and his wife ______ in Europe last year.","o":["were","was","are","has been"],"a":0,"e":"Plural subject in the past."},{"q":"The privates ______ lunch right now.","o":["are eating","eats","eating","was eating"],"a":0,"e":"right now with a plural subject."},{"q":"I ______ Brussels next year.","o":["visited","am visiting","did visit","have visit"],"a":1,"e":"A settled plan -> present progressive with future meaning."},{"q":"By this time next year, I ______ all my exams.","o":["will take","will have taken","have taken","take"],"a":1,"e":"By this time next year -> future perfect."},{"q":"While I was driving to work this morning, I ______ about my briefing.","o":["think","was think","will think","was thinking"],"a":3,"e":"Two actions in progress at the same time: past progressive."},{"q":"Before the firemen could extinguish the flames, the house ______.","o":["will already burn down","was already burn down","is already burn down","had already burned down"],"a":3,"e":"An earlier action in the past."},{"q":"First, I went to the movie; then, I ______ some pizza.","o":["eat","will eat","ate","am eating"],"a":2,"e":"A sequence of past actions: simple past."},{"q":"Because it was raining, we ______ the picnic.","o":["cancel","canceled","are cancel","cancels"],"a":1,"e":"Backshift of tense into the past."},{"q":"I ______ the taste of raw tomatoes ever since I was a little boy.","o":["like","am like","liking","have liked"],"a":3,"e":"ever since -> present perfect."},{"q":"I need to borrow some money because I ______ to bring my wallet this morning.","o":["forget","am forget","will forget","forgot"],"a":3,"e":"this morning is a finished period -> simple past."},{"q":"While I was in college, I ______ on most of my tests.","o":["cheat","have cheat","cheated","am cheating"],"a":2,"e":"A finished period in the past: simple past."},{"q":"You may leave now, unless you ______ to hear the same lecture again.","o":["wanted","want","are wanting","will be wanted"],"a":1,"e":"After unless, use the present simple."},{"q":"Just as I was walking into the classroom, the bell ______.","o":["ring","ringing","rang","has rung"],"a":2,"e":"A short action that interrupts another one: simple past (rang)."},{"q":"I will sit in the car and wait while you ______ in the store.","o":["shops","shopped","will be shop","shop"],"a":3,"e":"After while with future meaning, use the present simple."},{"q":"Just as I walked outside, it ______ to rain.","o":["started","starts","starting","is start"],"a":0,"e":"Backshift of tense into the past."},{"q":"Before I mail this letter tomorrow, I ______ it.","o":["am reread","will reread","did reread","rereading"],"a":1,"e":"The main clause is in the future."},{"q":"I was sitting in my car when ______.","o":["the storm start","starts the storm","the storm started","the storm is start"],"a":2,"e":"Subject-verb order + simple past."},{"q":"My mother ______ the carpet when I got home yesterday afternoon.","o":["is hoovering","was hoovering","were hoovering","has been hoovering"],"a":1,"e":"An action in progress that was interrupted: past progressive."},{"q":"We ______ the flight tickets yet.","o":["don't book","hasn't booked","have booked","haven't booked"],"a":3,"e":"yet goes with the present perfect negative."},{"q":"I was answering the phone and didn't realize you ______ outside.","o":["wait","were waiting","had waited","are waiting"],"a":1,"e":"An action in progress in the past."},{"q":"Deborah ______ a car before she went to New Zealand.","o":["had have","had had","have had","has had"],"a":1,"e":"Earlier action, so the past perfect of have."},{"q":"Sony offered Sabine a job before she ______ her degree.","o":["finish","had finished","was finishing","finishes"],"a":1,"e":"An earlier action in the past."},{"q":"I had breakfast quite early, then I ______ to the bus stop and caught the bus.","o":["had gone","had went","went","goed"],"a":2,"e":"A sequence of actions: simple past."},{"q":"By the end of this year, I ______ enough money to buy a computer.","o":["will save","save","will have saved","had saved"],"a":2,"e":"By the end of -> future perfect."}]}]};
